		--files-test "$TOOLS/files_test.sh" --label selftest --turnin out.txt --strict
want_out   "shell_test: files mode says it read the generator's output" \
	'checking a fresh copy built from generators/gen_ok.sh' -- \
	"$SH" "$TOOLS/shell_test.sh" --generator "$WORK/gen_ok.sh" --mode files \
