cat "$WORK/cv/README.md" "$WORK/cv/docs/testing.md" > "$WORK/cv/docs/reference.md"
rm -f "$WORK/cv/README.md" "$WORK/cv/docs/testing.md" "$WORK/cv/docs/loop.md" "$WORK/cv/docs/readloop.md" \
	"$WORK/cv/docs/loop.sh" "$WORK/cv/docs/quoted.sh" "$WORK/cv/docs/zlist.sh" \
	"$WORK/cv/docs/trimloop.sh" "$WORK/cv/docs/fields.sh" \
	"$WORK/cv/tools/tests/boxcc.sh" "$WORK/cv/tools/boxrun.sh" "$WORK/cv/tools/handrun.sh" \
	"$WORK/cv/tools/toyvar_check.sh" "$WORK/cv/tools/handvar.sh" "$WORK/cv/tools/toyrun.sh" \
	"$WORK/cv/tools/toynew_check.sh" "$WORK/cv/tools/toyrow_check.sh" "$WORK/cv/tools/toyld_check.sh" \
	"$WORK/cv/tools/toynold_check.sh" "$WORK/cv/tools/toypair_check.sh" "$WORK/cv/tools/toybad_check.sh" \
	"$WORK/cv/tools/toyforget_check.sh" "$WORK/cv/tools/toylist_check.sh"
sed '/^_PINNED_CC_RUNNERS = {$/,/^}$/d' "$WORK/cv/tools/defs.bzl" > "$WORK/cv_defs.tmp" &&
	mv "$WORK/cv_defs.tmp" "$WORK/cv/tools/defs.bzl"
cv_submit "$_cv_mods" > "$WORK/cv/tools/submit.sh"
! st_mine || $CONV > "$WORK/cv.ladder" 2>&1
# (An absence proves nothing from a run that stopped early: this run still
# reports the fixture's ungated sanitize pair, from a check after both.)
want_out "conventions: the second run ran to the end" \
	'has a c_function(sanitize) whose c_diff does not gate on it' -- cat "$WORK/cv.ladder"
want_broken_none "conventions: ...both are docs/reference.md's to hold" \
	'the level ladder is spelled out' -- cat "$WORK/cv.ladder"
want_broken_none "conventions: ...and a table of REPLACE_ME is not" \
	'REMOTES table holds a row' -- cat "$WORK/cv.ladder"
rm -rf "$WORK/cv/docs" "$WORK/cv.ladder"

want_out "conventions: an ungated sanitize pair is reported" \
	"c-piscine/c-piscine-c-99/BUILD.bazel has a c_function(sanitize) whose c_diff does not gate on it" -- \
	$CONV

want_broken_none "conventions: a correctly gated sanitize pair is accepted" \
	"c-piscine/c-piscine-c-98/BUILD.bazel has a c_function" -- \
	$CONV

# ------------------------ conventions: dump harnesses, fixtures, module tests
# A dump's harness publishes the address it passes (finding 048): without an
# "@addr" line, diff_output.sh --sanitize compares the column's shape and
# never its value. Both fixture modules have c_function(sanitize = True) on
# ex07's t.c, c-98's writing the marker in code, c-99's only in a comment.
mkdir -p "$WORK/cv/c-piscine/c-piscine-c-98/tests/ex07" "$WORK/cv/c-piscine/c-piscine-c-99/tests/ex07"
printf '#include <stdio.h>\n/* conventions: above 4 GiB -- a toy, which dumps nothing */\nint\tmain(void)\n{\n\tprintf("@addr %%016llx\\n", 0ULL);\n}\n' \
	> "$WORK/cv/c-piscine/c-piscine-c-98/tests/ex07/t.c"
# And where the block lives (finding 048): below 4 GiB, as a reader's heap is,
# an address cut to 32 bits is the real one. A reader that turns a pointer
# into a number calls dio_high (tools/diffio.h); a program that publishes an
# address calls it, or says where its blocks are -- c-98's t.c above does.
mkdir -p "$WORK/cv/c-piscine/c-piscine-c-98/tests/ex26" "$WORK/cv/c-piscine/c-piscine-c-99/tests/ex81" \
	"$WORK/cv/c-piscine/c-piscine-c-99/tests/ex82"
printf '#include "diffio.h"\nint\tmain(void)\n{\n\tunsigned char\t*b;\n\n\tb = dio_high(malloc(4), 4);\n\treturn ((uintptr_t)b == 0);\n}\n' \
	> "$WORK/cv/c-piscine/c-piscine-c-98/tests/ex26/diff_high.c"
printf '#include "diffio.h"\n/* dio_high( in a comment is no call */\nint\tmain(void)\n{\n\tunsigned char\t*b;\n\n\tb = malloc(4);\n\treturn ((uintptr_t)b == 0);\n}\n' \
	> "$WORK/cv/c-piscine/c-piscine-c-99/tests/ex81/diff_low.c"
printf '#include <stdio.h>\nint\tmain(void)\n{\n\tprintf("@addr %%016llx\\n", 0ULL);\n}\n' \
	> "$WORK/cv/c-piscine/c-piscine-c-99/tests/ex82/t_pub.c"
printf '#include <stdio.h>\n/* no @addr line here */\nint\tmain(void)\n{\n\treturn (0);\n}\n' \
	> "$WORK/cv/c-piscine/c-piscine-c-99/tests/ex07/t.c"
# The harness is found wherever Starlark would find it, and a call whose
# harness cannot be found is reported, never passed over: the rule read only
# a `test = "..."` keyword in a call at column 0 and skipped a harness that
# was not there, so a positional harness, a call in a list comprehension and
# a misnamed harness all went unchecked (each quiet before).
mkdir -p "$WORK/cv/c-piscine/c-piscine-c-99/tests/ex80"
printf 'int\tmain(void)\n{\n\treturn (0);\n}\n' > "$WORK/cv/c-piscine/c-piscine-c-99/tests/ex80/t8.c"
cp "$WORK/cv/c-piscine/c-piscine-c-99/BUILD.bazel" "$WORK/cv.addr.keep"
{
	printf '\nc_function("80", "ft_y", "t8.c", sanitize = True)\n\n'
	printf '[\n    c_function(num = n, fn = "ft_z", test = "t.c", sanitize = True)\n'
	printf '    for n in ["09"]\n]\n\n'
	printf 'c_function(num = "10", fn = "ft_v", test = "missing.c", sanitize = True)\n'
} >> "$WORK/cv/c-piscine/c-piscine-c-99/BUILD.bazel"
! st_mine || $CONV > "$WORK/cv.addr" 2>&1
mv "$WORK/cv.addr.keep" "$WORK/cv/c-piscine/c-piscine-c-99/BUILD.bazel"
want_out "conventions: a sanitize harness that publishes no @addr is reported" \
	"c-piscine/c-piscine-c-99/tests/ex07/t.c publishes no @addr line" -- cat "$WORK/cv.addr"
want_broken_none "conventions: ...and one that publishes it is not" \
	"c-piscine/c-piscine-c-98/tests/ex07/t.c publishes" -- cat "$WORK/cv.addr"
want_out "conventions: ...a harness passed by position is read" \
	"c-piscine/c-piscine-c-99/tests/ex80/t8.c publishes no @addr line" -- cat "$WORK/cv.addr"
want_out "conventions: ...a call in a comprehension is reported, not passed over" \
	"its num is not a literal" -- cat "$WORK/cv.addr"
want_out "conventions: ...and so is a harness that is not there" \
	"c-piscine/c-piscine-c-99/tests/ex10/missing.c, a sanitize harness its c_function names, does not exist" -- \
	cat "$WORK/cv.addr"
want_out "conventions: a reader checking an address below 4 GiB is reported" \
	"c-piscine/c-piscine-c-99/tests/ex81/diff_low.c turns a pointer into a number, and puts no block above 4 GiB" -- \
	cat "$WORK/cv.addr"
want_broken_none "conventions: ...and one that calls dio_high is not" \
	"c-piscine/c-piscine-c-98/tests/ex26/diff_high.c turns a pointer" -- cat "$WORK/cv.addr"
want_out "conventions: a program publishing an address says where its blocks are" \
	"c-piscine/c-piscine-c-99/tests/ex82/t_pub.c publishes an address, and does not say its blocks are above 4 GiB" -- \
	cat "$WORK/cv.addr"
want_broken_none "conventions: ...and one that says so is not" \
	"c-piscine/c-piscine-c-98/tests/ex07/t.c publishes an address" -- cat "$WORK/cv.addr"
rm -rf "$WORK/cv/c-piscine/c-piscine-c-98/tests/ex07" "$WORK/cv/c-piscine/c-piscine-c-99/tests/ex07" \
	"$WORK/cv/c-piscine/c-piscine-c-99/tests/ex80" "$WORK/cv/c-piscine/c-piscine-c-98/tests/ex26" \
	"$WORK/cv/c-piscine/c-piscine-c-99/tests/ex81" "$WORK/cv/c-piscine/c-piscine-c-99/tests/ex82" \
	"$WORK/cv.addr"

# Output fixtures and --harness-fixture. The check is an awk parse of
# defs.bzl, the kind of thing that can quietly stop matching and go on saying
# OK, so each shape it tells apart gets an arm: a fixture built with a plain
# cc_binary, --harness-fixture on a binary the macro did not build with
# _output_fixture_binary, and the correct pairing it must accept. The
# _LAYER_LEVEL fake above is put back after.
cp "$WORK/cv/tools/defs.bzl" "$WORK/cv_defs.bak"
{
	printf '_LAYER_LEVEL = {\n    "norm": 1,\n    "widget": 3,\n}\n\n'
	printf 'def plain(ex):\n    test_f = "tests/%%s/test_x.c" %% ex\n'
	printf '    cc_binary(\n        name = "b",\n        srcs = [test_f],\n    )\n\n'
	printf 'def unbuffered(ex):\n    test_f = "tests/%%s/test_x.c" %% ex\n'
	printf '    _student_bin(\n        name = "c_bin",\n        harness = [test_f],\n        deps = [":f"],\n    )\n\n'
	printf 'def wrongflag(ex):\n    diffbin = ex + "_diffbin"\n'
	printf '    _test(\n        args = [\n            "--bin",\n'
	printf '            "$(location :%%s)" %% diffbin,\n            "--harness-fixture",\n'
	printf '        ],\n    )\n\n'
	printf 'def rightflag(ex):\n    test_f = "tests/%%s/test_x.c" %% ex\n    binname = ex + "_bin"\n'
	printf '    _output_fixture_binary(\n        name = binname,\n        harness = [test_f],\n        deps = [":f"],\n    )\n'
	printf '    _test(\n        args = [\n            "--bin",\n'
	printf '            "$(location :%%s)" %% binname,\n            "--harness-fixture",\n'
	printf '        ],\n    )\n'
} > "$WORK/cv/tools/defs.bzl"
want_out "conventions: a cc_binary built from a harness main is reported" \
	'a cc_binary built from a harness main' -- \
	$CONV
want_out "conventions: a _student_bin built around a harness main is reported" \
	'a _student_bin built from a harness main, not through _output_fixture_binary' -- \
	$CONV
want_broken_none "conventions: ...and an _output_fixture_binary around one is not" \
	'_output_fixture_binary around something' -- \
	$CONV
want_out "conventions: --harness-fixture on another binary is reported" \
	'--harness-fixture on diffbin' -- \
	$CONV
want_broken_none "conventions: ...and on an _output_fixture_binary it is not" \
	'--harness-fixture on binname' -- \
	$CONV
cp "$WORK/cv_defs.bak" "$WORK/cv/tools/defs.bzl"
# The tests of a whole module (deliverable_files) are named alike in the
# audit's _MODULE_TESTS, in first_red.sh's MODULE_TESTS and in the docs: one
# first_red does not know is filed as an exercise named '-'.
#
# In the same two runs: the files layers' excludes and //tools:submit's are
# one list of extensions, and a .git directory is left out of the globs --
# submit keeps its scratch repository at deliverable/.git, which git never
# pushes, and the files layers once reported it after every first submit.
# cv_mt: the saved run, with its status, so a run that broke (exit 2) fails
# the arms that look for an absence.
cv_mt() { cat "$WORK/cv.modtests"; return "$(cat "$WORK/cv.modtests.rc")"; }
{
	cat "$WORK/cv_defs.bak"
	printf '\n_MODULE_TESTS = {\n    "deliverable_files": "files",\n}\n'
	printf '\n_BUILD_PRODUCTS = ["*.o", "*.a"]\n'
	printf '\ndef _not_build_products(d):\n    return [d + "/**/" + p for p in _BUILD_PRODUCTS]\n'
	printf '\ndef stray(where):\n    return native.glob([where + "/**"], allow_empty = True)\n'
} > "$WORK/cv/tools/defs.bzl"
_cv_glob=$(grep -n 'native.glob(\[where' "$WORK/cv/tools/defs.bzl" | cut -d: -f1)
{
	cv_submit "$_cv_mods"
	printf "git add -A -- . ':(exclude)*.o' ':(exclude)*.a' ':(exclude)*.gch'\n"
} > "$WORK/cv/tools/submit.sh"
printf "#!/bin/sh\nMODULE_TESTS='other_files'\n" > "$WORK/cv/tools/first_red.sh"
if st_mine; then $CONV > "$WORK/cv.modtests" 2>&1; echo $? > "$WORK/cv.modtests.rc"; fi
want_out "conventions: first_red's module tests disagreeing with the audit's" \
	"first_red.sh's MODULE_TESTS disagrees" -- cv_mt
want_out "conventions: ...and one the docs never name" \
	'docs/reference.md never names deliverable_files' -- cv_mt
want_out "conventions: the files layers leaving out other files than submit" \
	"leave out other files than //tools:submit" -- cv_mt
want_out "conventions: ...naming the extension only one of them has" \
	"':(exclude)': *.a *.gch *.o" -- cv_mt
want_out "conventions: a glob of the turn-in taking in .git" \
	'take in a .git directory' -- cv_mt
# ...and a glob of a whole tree that does not use the list at all.
want_out "conventions: a glob of a whole tree without _not_build_products" \
	"tools/defs.bzl:$_cv_glob" -- cv_mt
printf "#!/bin/sh\nMODULE_TESTS='deliverable_files'\n" > "$WORK/cv/tools/first_red.sh"
{
	cat "$WORK/cv_defs.bak"
	printf '\n_MODULE_TESTS = {\n    "deliverable_files": "files",\n}\n'
	printf '\n_BUILD_PRODUCTS = ["*.o", "*.a", "*.gch"]\n'
	printf '\ndef _not_build_products(d):\n    return [d + "/**/" + p for p in _BUILD_PRODUCTS] + [d + "/**/.git/**"]\n'
	# The exclude on a line of its own, past a comment with a parenthesis in
	# it; a glob of the harness's own tests/; a docstring naming a glob.
	printf '\ndef stray(where):\n    """Not native.glob([where + "/**"]) alone."""\n'
	printf '    return native.glob(\n        [where + "/**"],\n'
	printf '        # what submit leaves out (and .git)\n'
	printf '        exclude = _not_build_products(where),\n        allow_empty = True,\n    )\n'
	printf '\ndef own(ex):\n    return native.glob(["tests/%%s/**" %% ex], allow_empty = True)\n'
} > "$WORK/cv/tools/defs.bzl"
if st_mine; then $CONV > "$WORK/cv.modtests" 2>&1; echo $? > "$WORK/cv.modtests.rc"; fi
want_broken_none "conventions: ...agreeing, they are not reported" \
	"MODULE_TESTS disagrees" -- cv_mt
want_broken_none "conventions: ...one list of extensions is not" \
	"leave out other files than" -- cv_mt
want_broken_none "conventions: ...nor a glob that leaves .git out" \
	'take in a .git directory' -- cv_mt
want_broken_none "conventions: ...nor a glob of a whole tree through the list" \
	'a glob of a whole turn-in tree' -- cv_mt
rm -f "$WORK/cv/tools/first_red.sh" "$WORK/cv.modtests" "$WORK/cv.modtests.rc"
cp "$WORK/cv_defs.bak" "$WORK/cv/tools/defs.bzl"
cv_submit "$_cv_mods" > "$WORK/cv/tools/submit.sh"
# A CORPUS RUNNER THAT CANNOT REPLAY UNDER A MEMORY CHECKER (finding 113), and
# _CORPUS_RUNNERS held to the runners: one that takes --bin and --oracle and
# sweeps must take the memory options and be listed, and a listed one must
# exist and take them. The probes are moved out of the way after.
{
	cat "$WORK/cv_defs.bak"
	printf '\n_CORPUS_RUNNERS = [\n    "//tools:probe_corpus_mem.sh",\n    "//tools:probe_corpus_gone.sh",\n]\n'
} > "$WORK/cv/tools/defs.bzl"
_cr_opts='while [ $# -gt 0 ]; do\n\tcase "$1" in\n\t\t--bin) BIN="$2"; shift 2 ;;\n\t\t--oracle) O="$2"; shift 2 ;;\n%s\t\t*) exit 2 ;;\n\tesac\ndone\n'
_cr_mem='\t\t--sanitized) rl_mem_opt "$@"; shift "$RL_MEM_SHIFT" ;;\n'
for _cr in plain mem unlisted; do
	{
		printf '#!/bin/sh\nset -u\n. "$RL_LIB"\n'
		# shellcheck disable=SC2059 # the format is the option loop, kept in one place
		if [ "$_cr" = plain ]; then printf "$_cr_opts" ''; else printf "$_cr_opts" "$_cr_mem"; fi
		printf 'rl_sweep_next 5 || exit 1\n'
		[ "$_cr" = plain ] || printf 'rl_mem_run -- "$O"\n'
	} > "$WORK/cv/tools/probe_corpus_$_cr.sh"
done
want_out "conventions: a corpus runner without the memory options is reported" \
	'probe_corpus_plain.sh replays a generated corpus and cannot replay it under a memory checker' -- \
	$CONV
want_out "conventions: ...and one _CORPUS_RUNNERS does not list" \
	'probe_corpus_unlisted.sh replays a corpus, and tools/defs.bzl' -- \
	$CONV
want_out "conventions: ...and a listed runner that is gone" \
	'_CORPUS_RUNNERS names tools/probe_corpus_gone.sh, which does not exist' -- \
	$CONV
want_broken_none "conventions: ...but a listed one with them is not" \
	'probe_corpus_mem.sh replays' -- \
	$CONV
rm -f "$WORK/cv/tools/probe_corpus_plain.sh" "$WORK/cv/tools/probe_corpus_mem.sh" \
	"$WORK/cv/tools/probe_corpus_unlisted.sh"
# A CORPUS RUNNER'S GATE IS rl_gate: BSQ's and Rush 01's ran the differ
# themselves, and BSQ's handed the program no map, so its corpora SKIPped on
# every correct program. A listed runner that runs the variable --gate-differ
# sets is reported, and so is one that takes the option and never calls
# rl_gate; the one that hands the differ to rl_gate is not.
{
	cat "$WORK/cv_defs.bak"
	printf '\n_CORPUS_RUNNERS = [\n    "//tools:probe_gate_hand.sh",\n    "//tools:probe_gate_lib.sh",\n]\n'
} > "$WORK/cv/tools/defs.bzl"
for _cr in hand lib; do
	{
		printf '#!/bin/sh\nset -u\n. "$RL_LIB"\nGD=""\n'
		printf 'while [ $# -gt 0 ]; do\n\tcase "$1" in\n\t\t--bin) BIN="$2"; shift 2 ;;\n'
		printf '\t\t--oracle) O="$2"; shift 2 ;;\n\t\t--gate-differ) GD="$2"; shift 2 ;;\n'
		printf '\t\t--sanitized) rl_mem_opt "$@"; shift "$RL_MEM_SHIFT" ;;\n'
		printf '\t\t*) exit 2 ;;\n\tesac\ndone\n'
		if [ "$_cr" = hand ]; then
			printf 'sh "$GD" --bin "$BIN" --expected x > /dev/null || exit 0\n'
		else
			printf 'rl_gate probe "$GD" "$BIN" x m\n'
		fi
		printf 'rl_sweep_next 5 || exit 1\nrl_mem_run -- "$O"\n'
	} > "$WORK/cv/tools/probe_gate_$_cr.sh"
done
want_out "conventions: a corpus runner that runs its gate itself is reported" \
	'tools/probe_gate_hand.sh runs its gate itself' -- $CONV
want_out "conventions: ...and for never calling rl_gate" \
	'tools/probe_gate_hand.sh takes --gate-differ and never calls rl_gate' -- $CONV
want_broken_none "conventions: ...but one that hands it to rl_gate is not" \
	'probe_gate_lib.sh runs its gate itself' -- $CONV
want_broken_none "conventions: ...nor said never to call it" \
	'probe_gate_lib.sh takes --gate-differ' -- $CONV
rm -f "$WORK/cv/tools/probe_gate_hand.sh" "$WORK/cv/tools/probe_gate_lib.sh"
cp "$WORK/cv_defs.bak" "$WORK/cv/tools/defs.bzl"
# A module builds no test program of its own: a cc_binary from a tests/ file in
# a module BUILD is reported, and so is --harness-fixture there.
cp "$WORK/cv/c-piscine/c-piscine-c-98/BUILD.bazel" "$WORK/cv_c98.bak"
printf 'cc_binary(\n    name = "x",\n    srcs = ["tests/ex00/x.c"],\n)\n' \
	>> "$WORK/cv/c-piscine/c-piscine-c-98/BUILD.bazel"
want_out "conventions: a module's cc_binary from a tests/ file is reported" \
	'c-98/BUILD.bazel builds its own binary from a tests/ file' -- \
	$CONV
cp "$WORK/cv_c98.bak" "$WORK/cv/c-piscine/c-piscine-c-98/BUILD.bazel"
want_broken_none "conventions: ...and without one nothing is" \
	'builds its own binary from a tests/ file' -- \
	$CONV
# A runner that reads a crash from a status above 128 -- which is also what
# `return (-1);` gives -- is reported, whatever its name: the debt list that
# once exempted nine runners by name (bsq_check.sh among them) is gone. The
# comparison is built from pieces so this file does not hold the pattern it
# greps for.
_gt="-gt"
printf '#!/bin/sh\nset -u\nrc=0\nif [ "$rc" %s 128 ]; then :; fi\n' "$_gt" \
	> "$WORK/cv/tools/probe_guess.sh"
cp "$WORK/cv/tools/probe_guess.sh" "$WORK/cv/tools/bsq_check.sh"
want_out "conventions: a runner guessing a crash from its status is reported" \
	'probe_guess.sh reads how a program ended from its status' -- \
	$CONV
want_out "conventions: ...under a name once on the debt list too" \
	'bsq_check.sh reads how a program ended from its status' -- \
	$CONV
rm -f "$WORK/cv/tools/probe_guess.sh" "$WORK/cv/tools/bsq_check.sh"
# --------------------------------- conventions: how a run ended, Python flags
# The same guess in the other spellings the rule once let through (review of
# wave 3): one probe each, one run of the gate, one arm per probe. Numbers go
# in as printf arguments, as above. The timeout arm `124 | 137)` was let
# through while a timeout killed tools/exit_status too; the helper keeps the
# time itself now, so that arm is a guess like the others. An awk length test
# that happens to hold 150, and a status test under a not-a-program-status
# line (tools/student_build.sh's toolchain), must stay quiet.
_cv_g() { printf '#!/bin/sh\nset -u\nrc=0\n%s\n' "$2" > "$WORK/cv/tools/probe_g_$1.sh"; }
_cv_g gt127 "$(printf 'if [ "$rc" %s %s ]; then :; fi' "$_gt" 127)"
_cv_g nospace "$(printf 'sig=$((rc-%s))' 128)"
_cv_g dollarq "$(printf 'sig=$(($? - %s))' 128)"
_cv_g eq "$(printf 'if [ "$rc" -eq %s ]; then :; fi' 134)"
_cv_g str "$(printf 'if [ "$rc" = "%s" ]; then :; fi' 137)"
_cv_g label "$(printf 'case "$rc" in\n\t%s) : ;;\nesac' 139)"
_cv_g timeout "$(printf 'case "$rc" in\n\t%s | %s) : ;;\nesac' 124 137)"
_cv_g awk "$(printf 'awk %s' "'{ if (length(\$0) > 150) print }'")"
_cv_g toolchain "$(printf '# conventions: not-a-program-status -- %s\nif [ "$rc" %s %s ]; then :; fi' \
	'a probe: a compiler, not a program' -ge 126)"
_cv_g untold "$(printf '# a plain comment\nif [ "$rc" %s %s ]; then :; fi' -ge 126)"
! st_mine || $CONV > "$WORK/cv_guess.out" 2>&1
_cv_rc=$?
# The gate's own status travels with its output, so a run that broke (2) fails
# every arm below as a harness error instead of being grepped for a line.
cv_guess() { cat "$WORK/cv_guess.out"; return "$_cv_rc"; }
for _s in gt127 nospace dollarq eq str label timeout; do
	want_out "conventions: the guess spelt as '$_s' is reported" \
		"probe_g_$_s.sh reads how a program ended from its status" -- cv_guess
done
want_broken_none "conventions: ...not a 150 that is no status" \
	'probe_g_awk.sh reads how' -- cv_guess
want_broken_none "conventions: ...nor a line marked not-a-program-status" \
	'probe_g_toolchain.sh reads how' -- cv_guess
want_out "conventions: ...which a plain comment above does not do" \
	'probe_g_untold.sh reads how a program ended from its status' -- cv_guess
rm -f "$WORK"/cv/tools/probe_g_*.sh "$WORK/cv_guess.out"
want_broken_none "conventions: ...and with no guess, nothing is" \
	'reads how a program ended from its status' -- \
	$CONV

# --keep_going in .bazelrc. Without it a student's compile error ends the run
# and the rest says NO STATUS, and the docs promise it is on. A .bazelrc that
# only mentions the flag in a comment, or sets it for one command, is not one
# that sets it; the fixture's .bazelrc is removed again after, as it came.
printf '# build --keep_going\ntest --keep_going\n' > "$WORK/cv/.bazelrc"
want_out "conventions: a .bazelrc without build --keep_going is reported" \
	".bazelrc no longer sets build --keep_going" -- \
	$CONV
printf 'build --keep_going\n' > "$WORK/cv/.bazelrc"
want_broken_none "conventions: and one that sets it is not" \
	".bazelrc no longer sets build --keep_going" -- \
	$CONV

# Python targets print no rules_python banner on a fresh clone (finding 047):
# a BUILD file declaring one needs .bazelrc's explicit-init flag, and every
# requirement of a file MODULE.bazel hands rules_python carries a --hash (a
# continued line counts as its requirement's). One run without the flag, one
# with; the fixture's files go back as they came.
cp "$WORK/cv/c-piscine/c-piscine-c-98/BUILD.bazel" "$WORK/cv_c98_py.bak"
printf '\npy_binary(\n    name = "p",\n    srcs = ["p.py"],\n)\n' \
	>> "$WORK/cv/c-piscine/c-piscine-c-98/BUILD.bazel"
printf 'pip.parse(\n    requirements_lock = "//tools:req.txt",\n)\n' > "$WORK/cv/MODULE.bazel"
printf '# pinned\na==1 \\\n    --hash=sha256:00ff\nb==2\n' > "$WORK/cv/tools/req.txt"
! st_mine || $CONV > "$WORK/cv.py" 2>&1
want_out "conventions: a Python target without the explicit-init flag" \
	'.bazelrc no longer sets --incompatible_default_to_explicit_init_py' -- cat "$WORK/cv.py"
want_out "conventions: a requirement with no --hash is reported" \
	'tools/req.txt:4: b==2' -- cat "$WORK/cv.py"
want_broken_none "conventions: ...and a hashed one over two lines is not" \
	'tools/req.txt:2:' -- cat "$WORK/cv.py"
printf 'build --keep_going\ncommon --incompatible_default_to_explicit_init_py\n' > "$WORK/cv/.bazelrc"
want_broken_none "conventions: ...and with the flag, the Python target is fine" \
	'explicit_init_py' -- $CONV
cp "$WORK/cv_c98_py.bak" "$WORK/cv/c-piscine/c-piscine-c-98/BUILD.bazel"
rm -f "$WORK/cv/MODULE.bazel" "$WORK/cv/tools/req.txt" "$WORK/cv.py" "$WORK/cv_c98_py.bak"
rm -f "$WORK/cv/.bazelrc"

# An output root in a tracked rc file. An rc file cannot say "per user", so the
# `startup --output_user_root=/tmp/bazelcache` .bazelrc carried was one path
# for every user of a campus box: the second student's build waited on the
# first one's lock (finding 001). tools/bazel supplies the per-user default
# now, and this keeps the shared literal from coming back. A commented one is
# not a setting.
printf 'build --keep_going\nstartup --output_user_root=/tmp/bazelcache\n' > "$WORK/cv/.bazelrc"
want_out "conventions: a .bazelrc naming an output root is reported" \
	".bazelrc names a shared place for Bazel's state" -- \
	$CONV
printf 'build --keep_going\n# startup --output_user_root=/tmp/x\n' > "$WORK/cv/.bazelrc"
want_broken_none "conventions: ...and a commented one is not" \
	".bazelrc names a shared place" -- \
	$CONV
# ...in ANY rc file and ANY flag that places state. The rule read two files and
# one flag, and an imported tools/*.bazelrc with a shared --disk_cache is the
# same collision. %workspace% is per checkout, the example's CHANGEME is a path
# to replace, and .bazelrc.local is the one file where an absolute path is the
# point (setup.sh writes it, per checkout, gitignored).
printf 'build --disk_cache=/tmp/shared-cache\n' > "$WORK/cv/tools/ci.bazelrc"
printf 'startup --output_user_root=/tmp/CHANGEME-login/bazel\n' > "$WORK/cv/.bazelrc.local.example"
printf 'startup --output_user_root=/goinfre/probe/bazel\n' > "$WORK/cv/.bazelrc.local"
want_out "conventions: a shared --disk_cache in another rc file is reported" \
	"tools/ci.bazelrc names a shared place for Bazel's state" -- \
	$CONV
want_broken_none "conventions: ...not the example's CHANGEME" \
	".bazelrc.local.example names a shared place" -- \
	$CONV
want_broken_none "conventions: ...nor .bazelrc.local" \
	".bazelrc.local names a shared place" -- \
	$CONV
printf 'build --disk_cache=%%workspace%%/.cache\n' > "$WORK/cv/tools/ci.bazelrc"
want_broken_none "conventions: ...nor a path under %workspace%" \
	"tools/ci.bazelrc names" -- \
	$CONV
# ...and one that is a symlink, as under `bazel test` every file is (V23).
printf 'build --disk_cache=/tmp/shared-cache\n' > "$WORK/cv_linked.rc"
ln -s "$WORK/cv_linked.rc" "$WORK/cv/tools/linked.bazelrc"
want_out "conventions: ...and one in an rc file that is a symlink" \
	"tools/linked.bazelrc names a shared place for Bazel's state" -- \
	$CONV
rm -f "$WORK/cv/tools/linked.bazelrc" "$WORK/cv_linked.rc"
rm -f "$WORK/cv/.bazelrc" "$WORK/cv/tools/ci.bazelrc" "$WORK/cv/.bazelrc.local.example" \
	"$WORK/cv/.bazelrc.local"

# ---------------------------------- conventions: the registry of issued files
# The registry of 42's own files (tools/resources.tsv). Its texts disagreed
# about where each file goes -- "its folder", "wherever you like" -- while the
# harness read exactly one path (findings 016, 161). A made-up project file,
# data.bin, registered with one doc that must name its path: a doc that sends
# the student to "its folder" instead is reported twice over, once for the
# vague place and once for the missing path; the same doc naming the path is
# not. A BUILD glob of one literal name stages a file the checkout may not
# have, which is 42's material's shape, so an unregistered one is reported.
mkdir -p "$WORK/cv/docs"
printf 'c-piscine/c-piscine-c-98\tdata.bin\tc-piscine/c-piscine-c-98/data.bin\tharness\t*data.bin\t-\tdocs/where.md\tthe intranet\n' \
	> "$WORK/cv/tools/resources.tsv"
printf 'fixtures = glob(["data.bin"], allow_empty = True)\n' >> "$WORK/cv/c-piscine/c-piscine-c-98/BUILD.bazel"
printf 'fixtures = glob(["other.bin"], allow_empty = True)\n' >> "$WORK/cv/c-piscine/c-piscine-c-99/BUILD.bazel"
printf 'Save data.bin in its folder.\n' > "$WORK/cv/docs/where.md"
want_out "conventions: a doc without a registered file's path is reported" \
	"docs/where.md mentions data.bin without its one path" -- \
	$CONV
want_out "conventions: ...and one sending it to 'its folder' too" \
	"a text sends a student to a vague place for 42's data.bin" -- \
	$CONV
want_out "conventions: an unregistered one-file glob is reported" \
	"globs the single file other.bin" -- \
	$CONV
want_broken_none "conventions: ...and a registered one is not" \
	"globs the single file data.bin" -- \
	$CONV
printf 'Save data.bin as c-piscine/c-piscine-c-98/data.bin.\n' > "$WORK/cv/docs/where.md"
want_broken_none "conventions: a doc naming the path is accepted" \
	"docs/where.md mentions data.bin" -- \
	$CONV

# HOW A BUILD FILE NAMES IT, read as Starlark. The file is not in the template,
# so a label naming it takes the whole package down there, and only there. The
# rule was "BUILD names the file", grepped -- a comment met it -- and the
# one-file-glob detector matched a glob only when it was written on one line,
# which is not how buildifier lays one out. Each fixture is c-98's BUILD file
# with one ending; the original goes back after.
cp "$WORK/cv/c-piscine/c-piscine-c-98/BUILD.bazel" "$WORK/cv/b98.orig"
cp "$WORK/cv/c-piscine/c-piscine-c-99/BUILD.bazel" "$WORK/cv/b99.orig"
_cv98=$(grep -v 'data.bin' "$WORK/cv/b98.orig")
cv98() { { printf '%s\n' "$_cv98"; printf "$@"; } > "$WORK/cv/c-piscine/c-piscine-c-98/BUILD.bazel"; }
cv98 '# data.bin is named here, in a comment only\n'
want_out "conventions: a registered file named only in a comment is reported" \
	"BUILD files never name data.bin outside a comment" -- \
	$CONV
cv98 'x(\n    num = "08",\n    fixtures = ["data.bin"],\n)\n'
want_out "conventions: ...one named as a label is reported" \
	"as a label (in fixtures)" -- \
	$CONV
cv98 'x(\n    fixtures = glob(\n        ["data.bin"],\n    ),\n)\n'
want_out "conventions: ...one in a glob that may not be empty too" \
	"in a glob without allow_empty = True" -- \
	$CONV
cv98 'subject(\n    exercises = {\n        "08": exercise(\n            files = ["data.bin"],\n            optional = ["data.bin"],\n        ),\n    },\n)\nx(\n    fixtures = glob(\n        ["data.bin"],\n        allow_empty = True,\n    ),\n)\n'
want_broken_none "conventions: ...but not a name list, nor a glob allowed empty" \
	"breaks the template" -- \
	$CONV
# A name list is a keyword OF ONE CALL: `file` is c_issued's name, and the
# same keyword of any other call may take a label. The exemption was the
# keyword alone, so this passed.
cv98 'x(\n    num = "08",\n    file = "data.bin",\n)\n'
want_out "conventions: ...but another call's file = is a label" \
	"as a label (in file)" -- \
	$CONV
# A cwd_files value is what a staged file is CALLED in the run folder (Rush
# 02 stages its own dictionary as 42's numbers.dict): a name, never a label.
# Its key is the label of what is staged, and naming 42's file there is one.
cv98 'x(\n    num = "08",\n    cases = [{\n        "name": "a",\n        "cwd_files": {"tests/ex08/own.bin": "data.bin"},\n        "args": ["1"],\n    }],\n)\n'
want_broken_none "conventions: ...nor the name a cwd_files case stages a file under" \
	"breaks the template" -- \
	$CONV
cv98 'x(\n    num = "08",\n    cases = [{\n        "name": "a",\n        "cwd_files": {"data.bin": "own.bin", "b": "c"},\n    }],\n)\n'
want_out "conventions: ...but the file a cwd_files case stages is a label" \
	"as a label (in cases)" -- \
	$CONV
{ grep -v 'other.bin' "$WORK/cv/b99.orig"
	printf 'x(\n    fixtures = glob(\n        ["other.bin"],\n        allow_empty = True,\n    ),\n)\n'; } \
	> "$WORK/cv/c-piscine/c-piscine-c-99/BUILD.bazel"
want_out "conventions: an unregistered one-file glob over lines is reported" \
	"globs the single file other.bin" -- \
	$CONV
cp "$WORK/cv/b98.orig" "$WORK/cv/c-piscine/c-piscine-c-98/BUILD.bazel"
cp "$WORK/cv/b99.orig" "$WORK/cv/c-piscine/c-piscine-c-99/BUILD.bazel"

# ---------------------------------- conventions: registry consumers, CR bytes
# A consumer is a test of the row's own project, which SKIPs naming the path
# while the file is absent. The registry's header promised this was checked,
# and nothing read the column.
printf 'c-piscine/c-piscine-c-98\tdata.bin\tc-piscine/c-piscine-c-98/data.bin\tharness\t*data.bin\t//c-piscine/c-piscine-c-99:ex00_output\tdocs/where.md\tthe intranet\n' \
	> "$WORK/cv/tools/resources.tsv"
want_out "conventions: a consumer outside the row's project is reported" \
	"consumer //c-piscine/c-piscine-c-99:ex00_output is not a target of c-piscine/c-piscine-c-98" -- \
	$CONV
printf 'c-piscine/c-piscine-c-98\tdata.bin\tc-piscine/c-piscine-c-98/data.bin\tharness\t*data.bin\t//c-piscine/c-piscine-c-98:ex00_output\tdocs/where.md\tthe intranet\n' \
	> "$WORK/cv/tools/resources.tsv"
want_broken_none "conventions: ...and one inside it is not" \
	"consumer //c-piscine" -- \
	$CONV

# A file the project turns in has its c_issued, whose test is red while the
# file is missing: the template ships no copy and its .gitignore keeps a
# student's out of commits, so nothing else said so (finding 162). Its `file`
# is a name, which c_issued globs, never a label.
_cv_reg=$(cat "$WORK/cv/tools/resources.tsv")
printf 'c-piscine/c-piscine-c-98\tdata.bin\tc-piscine/c-piscine-c-98/data.bin\tturn-in\t*data.bin\t-\tdocs/where.md\tthe intranet\n' \
	> "$WORK/cv/tools/resources.tsv"
want_out "conventions: a turned-in file with no c_issued is reported" \
	'data.bin is turned in, and c-piscine/c-piscine-c-98 has no c_issued' -- \
	$CONV
cv98 'c_issued(\n    num = "08",\n    file = "data.bin",\n)\nx(\n    fixtures = glob(["data.bin"], allow_empty = True),\n)\n'
want_broken_none "conventions: ...and one with it is not" 'has no c_issued' -- \
	$CONV
want_broken_none "conventions: ...whose file is a name, not a label" 'breaks the template' -- \
	$CONV
cp "$WORK/cv/b98.orig" "$WORK/cv/c-piscine/c-piscine-c-98/BUILD.bazel"
printf '%s\n' "$_cv_reg" > "$WORK/cv/tools/resources.tsv"

# A CR that `* text=auto eol=lf` strips on commit: Rush 02's crlf.dict was
# committed with LF only, so every clone's case tested nothing while the
# checkout that wrote it was green. A file holding a CR must match a -text
# rule of .gitattributes; one with no text rule at all is not checked.
mkdir -p "$WORK/cv/c-piscine/c-piscine-c-98/tests/ex20/fixtures"
printf '1: one\r\n' > "$WORK/cv/c-piscine/c-piscine-c-98/tests/ex20/fixtures/crlf.dict"
printf 'a note\r\n' > "$WORK/cv/c-piscine/c-piscine-c-98/notes.txt"
want_broken_none "conventions: a CR with no text rule in .gitattributes is not checked" \
	'a file holds a CR byte' -- $CONV
printf '* text=auto eol=lf\n**/tests/ex[0-9][0-9]/fixtures/** -text\n' > "$WORK/cv/.gitattributes"
want_out "conventions: a CR the text rule strips on commit is reported" \
	'    c-piscine/c-piscine-c-98/notes.txt' -- $CONV
want_broken_none "conventions: ...and one a -text rule covers is not" \
	'c-piscine-c-98/tests/ex20/fixtures/crlf.dict' -- $CONV
# A lone CR (one no LF follows) makes git take the whole file for binary
# and commit it as it is, CR LFs and all: nothing is stripped, so nothing
# is reported (V-d). The rule named every file holding a CR.
printf 'a\rb\n' > "$WORK/cv/c-piscine/c-piscine-c-98/lone.txt"
printf 'a\rb\r\n' > "$WORK/cv/c-piscine/c-piscine-c-98/mixed.txt"
want_broken_none "conventions: ...nor a lone CR, which git keeps" 'c-piscine-c-98/lone.txt' -- $CONV
want_broken_none "conventions: ...nor a CR LF beside one" 'c-piscine-c-98/mixed.txt' -- $CONV
rm -f "$WORK/cv/c-piscine/c-piscine-c-98/lone.txt" "$WORK/cv/c-piscine/c-piscine-c-98/mixed.txt"
rm -f "$WORK/cv/c-piscine/c-piscine-c-98/notes.txt"
want_broken_none "conventions: ...nor, then, anything" 'a file holds a CR byte' -- $CONV
# A clue, a script or a BUILD file is text the harness reads, never a case's
# bytes: a CR in one is refused even under a -text rule. The rule once
# covered all of tests/, and a CR typed into a clue was committed as it was.
_cr98=$WORK/cv/c-piscine/c-piscine-c-98/tests/ex20
cp "$_cr98/clues.tsv" "$WORK/cv/clues98.orig" 2> /dev/null || : > "$WORK/cv/clues98.orig"
printf 'Which byte ends this line?\r\n' > "$_cr98/clues.tsv"
printf '* text=auto eol=lf\n**/tests/ex[0-9][0-9]/** -text\n' > "$WORK/cv/.gitattributes"
want_out "conventions: a CR in a clue is reported under a -text rule" \
	'c-piscine/c-piscine-c-98/tests/ex20/clues.tsv (a harness text file' -- $CONV
want_broken_none "conventions: ...and a fixture's beside it is not" \
	'c-piscine-c-98/tests/ex20/fixtures/crlf.dict' -- $CONV
cp "$WORK/cv/clues98.orig" "$_cr98/clues.tsv"
[ -s "$_cr98/clues.tsv" ] || rm -f "$_cr98/clues.tsv"
rm -f "$WORK/cv/.gitattributes" "$WORK/cv/clues98.orig" "$WORK/cv/c-piscine/c-piscine-c-98/tests/ex20/fixtures/crlf.dict"

# CHANGELOG.md, in the shape the template build's --chain reads: dated lines,
# and at most one next-publish line, first.
printf '# Changelog\n\n- next publish: pull, then run setup\n- someday: this\n' > "$WORK/cv/CHANGELOG.md"
want_out "conventions: an undated CHANGELOG entry is reported" \
	'line 4: not "- YYYY-MM-DD: what to do"' -- \
	$CONV
printf '# Changelog\n\n- next publish: pull, then run setup\n- 2026-09-25: first\n' > "$WORK/cv/CHANGELOG.md"
want_broken_none "conventions: ...and a dated one is not" \
	"CHANGELOG.md has entries" -- \
	$CONV
rm -f "$WORK/cv/CHANGELOG.md"

# ------------------------------------ conventions: bazel run, first-red hints
# A script `bazel run` starts must find its files in the workspace: under
# `bazel run` nothing sits beside $0, not even a data dependency. init.sh and
# env_drift.sh read tools/drives.sh from a variable holding the directory of
# $0, both exited 2 under `bazel run`, and every arm stayed green, because the
# arms ran them from tools/. The binary is a module's, naming the script by
# label, as a module's generate target names tools/generate.sh.
printf 'sh_binary(\n    name = "run",\n    srcs = ["//tools:probe_run.sh"],\n)\n' \
	>> "$WORK/cv/c-piscine/c-piscine-c-99/BUILD.bazel"
printf '#!/bin/sh\nset -u\n_d=${0%%/*}\n. "$_d/helper.sh"\n' \
	> "$WORK/cv/tools/probe_run.sh"
want_out "conventions: a file read only beside \$0 is reported" \
	"tools/probe_run.sh:4: helper.sh, beside \$0 and nowhere else" -- \
	$CONV
{
	printf '#!/bin/sh\nset -u\nrequire() { :; }\nrequire dirname\n'
	printf 'WS="${BUILD_WORKSPACE_DIRECTORY:-$(cd "$(dirname "$0")/.." && pwd)}"\n'
	printf 'H="$(cd "$(dirname "$0")" && pwd)/helper.sh"\n'
	printf '[ -f "$H" ] || H="$WS/tools/helper.sh"\n. "$H"\n'
} > "$WORK/cv/tools/probe_run.sh"
want_broken_none "conventions: ...and one looked for in the workspace too is not" \
	"beside \$0 and nowhere else" -- \
	$CONV
rm -f "$WORK/cv/tools/probe_run.sh"
cp "$WORK/cv/b99.orig" "$WORK/cv/c-piscine/c-piscine-c-99/BUILD.bazel"

# First-red hints. ft_display_file shipped a member-less hint that listed the
# program's steps joined by a single "then", and the untouched stub printed it.
# An invented exercise here, in each shape the check has to tell apart: that
# form (reported); the same kind of row as a C file's fourth, keyed row, which
# a stub's first red does not reach (quiet); numbered steps in the fourth row
# of a SHELL exercise, whose rows all fire at once (reported, so the BUILD
# parse is proven too); a question that names an order without giving one
# -- "the first page", "then the author" -- (quiet); steps marked only by
# "and after that" and "and finally", which the detector once counted after
# punctuation alone (reported); and a plain statement, which the rule's "is a
# question" rules out (reported).
_cv99=$WORK/cv/c-piscine/c-piscine-c-99/tests
_cv98=$WORK/cv/c-piscine/c-piscine-c-98/tests
mkdir -p "$_cv99/ex00" "$_cv99/ex01" "$_cv99/ex02" "$_cv99/ex03" \
	"$_cv98/ex21" "$_cv98/ex05"
printf 'Fold the paper along the line, then cut along the crease.\n' \
	> "$_cv99/ex00/clues.tsv"
printf 'Fold it and after that cut it, and finally glue it: which glue holds?\n' \
	> "$_cv99/ex02/clues.tsv"
printf 'The crease goes on the outside.\n' > "$_cv99/ex03/clues.tsv"
{
	printf 'What is a crease?\tcrease\n'
	printf 'Which way does it fold?\tfold\n'
	printf 'How long is the cut?\tcut\n'
	printf 'Fold it, then cut it.\tedge\n'
} > "$_cv99/ex01/clues.tsv"
printf 'shell_exercise(num = "05", mode = "check")\n' \
	>> "$WORK/cv/c-piscine/c-piscine-c-98/BUILD.bazel"
{
	printf 'What is a crease?\tcrease\n'
	printf 'Which way does it fold?\tfold\n'
	printf 'How long is the cut?\tcut\n'
	printf '1) Fold it. 2) Cut it.\tedge\n'
} > "$_cv98/ex05/clues.tsv"
printf 'What is on the first page: the title, then the author? Where does it end?\n' \
	> "$_cv98/ex21/clues.tsv"

# The FAIL line for one clue file and the first row reported under it, so an
# arm that names a reason also names the file that gave it.
cv_rows() { $CONV 2>&1 | grep -A1 -F -- "$1 has a first-red hint"; }

want_out "conventions: a first-red hint chained with then is reported" \
	'c-piscine/c-piscine-c-99/tests/ex00/clues.tsv has a first-red hint written as steps' -- \
	$CONV

want_broken_none "conventions: a keyed fourth row is out of first-red reach" \
	'c-piscine/c-piscine-c-99/tests/ex01/clues.tsv has a first-red' -- \
	$CONV

want_out "conventions: every row of a shell exercise's clues is checked" \
	'line 4 (numbered steps)' -- \
	cv_rows c-piscine/c-piscine-c-98/tests/ex05/clues.tsv

want_broken_none "conventions: a question naming an order is not a step list" \
	'c-piscine/c-piscine-c-98/tests/ex21/clues.tsv has a first-red' -- \
	$CONV

want_out "conventions: \"and finally\", \"and after that\" count as steps" \
	'line 1 (2 sequencing words)' -- \
	cv_rows c-piscine/c-piscine-c-99/tests/ex02/clues.tsv

want_out "conventions: a first-red statement with no question is reported" \
	'line 1 (no question)' -- \
	cv_rows c-piscine/c-piscine-c-99/tests/ex03/clues.tsv

# A clue row may name a program case (c_program's "name"), whose rows are bare
# lines, or "line N" of an output (finding 155); a label naming neither is a
# gate that never opens. An invented c_program with two cases, one of them
# written over several lines as buildifier lays it out, and a clue file with
# no expected.txt beside it: a case's name and any "line N" are accepted, a
# misspelt name is reported. And "line N" past an expected.txt's end.
# Case "one" is labeled (its rows are keyed by their first fields), on one
# line; case "two" is not, over several, with a dict of its own inside it.
printf '%s\n' 'c_program(' '    num = "10",' '    name = "toy",' '    cases = [' \
	'        {"name": "one", "expected": "a.txt", "labeled": True},' '        {' \
	'            "name": "two",' '            "expected": "b.txt",' '            "labeled": False,' \
	'            "cwd_files": {"x.dict": "x"},' '        },' '    ],' ')' \
	>> "$WORK/cv/c-piscine/c-piscine-c-98/BUILD.bazel"
mkdir -p "$_cv98/ex10" "$_cv98/ex11"
printf 'Which case is this?\tone\nWhat is on line 3?\tline 3\nWhich case is this?\ttow\nWhich one?\ttwo\n' \
	> "$_cv98/ex10/clues.tsv"
printf 'a\tv\nb\tw\n' > "$_cv98/ex11/expected.txt"
printf 'What is on line 2?\tline 2\nWhat is on line 5?\tline 5\n' > "$_cv98/ex11/clues.tsv"
cv_dead() { $CONV 2>&1 | grep -A4 -F -- "$1 names a case that does not exist"; }
want_out "conventions: a clue naming no program case is reported" 'line 3: tow' -- \
	cv_dead c-piscine/c-piscine-c-98/tests/ex10/clues.tsv
want_broken_none "conventions: ...a clue naming one is not" 'line 1: one' -- \
	cv_dead c-piscine/c-piscine-c-98/tests/ex10/clues.tsv
want_broken_none "conventions: ...nor one naming a case laid out over lines" 'line 4: two' -- \
	cv_dead c-piscine/c-piscine-c-98/tests/ex10/clues.tsv
want_broken_none "conventions: ...nor a line of a program's output" 'line 2: line 3' -- \
	cv_dead c-piscine/c-piscine-c-98/tests/ex10/clues.tsv
want_out "conventions: a line past the expected output is reported" 'line 2: line 5' -- \
	cv_dead c-piscine/c-piscine-c-98/tests/ex11/clues.tsv
want_broken_none "conventions: ...one within it is not" 'line 1: line 2' -- \
	cv_dead c-piscine/c-piscine-c-98/tests/ex11/clues.tsv
# A row keyed to a program case fires on that case's test wherever it sits,
# and the stub fails every case: it is a first-red row, however far down.
# So is one keyed to a line of the output, in a program's file: the rows
# keyed to other cases drop out of each case's test, so it fires from any
# row there. In a file that is no program's, the first three rows are the
# ones that can.
printf 'Case two prints a word.\ttwo\nLine three prints a word.\tline 3\n' >> "$_cv98/ex10/clues.tsv"
want_out "conventions: a row keyed to a program case is a first-red row" \
	'line 5 (no question)' -- cv_rows c-piscine/c-piscine-c-98/tests/ex10/clues.tsv
# "valgrind" keys a row to a program's memory arms (valgrind_test.sh); in a
# file that is no program's it names nothing.
printf 'What does valgrind say?\tvalgrind\n' >> "$_cv98/ex10/clues.tsv"
printf 'What does valgrind say?\tvalgrind\n' >> "$_cv98/ex11/clues.tsv"
want_broken_none "conventions: \"valgrind\" is a label in a program's hints" 'line 7: valgrind' -- \
	cv_dead c-piscine/c-piscine-c-98/tests/ex10/clues.tsv
want_out "conventions: ...and in no other file" 'line 3: valgrind' -- \
	cv_dead c-piscine/c-piscine-c-98/tests/ex11/clues.tsv
# A target that replays a corpus through a runner of its own keys its rows
# in the program's one clues.tsv by the name it passes as --case (ruling
# R7): BSQ's and Rush 01's readings once had a clue file each. An invented
# one, the name on the line after "--case" and on its line, and a label no
# test passes (reported). A --case followed by a variable, on the next line
# or on its own, is reported as unreadable, and a word quoted later is no
# label for it: the next quoted string on any later line used to be taken.
cp "$_cv98/ex10/clues.tsv" "$WORK/cv_ex10_keyed.tsv"
cp "$WORK/cv/c-piscine/c-piscine-c-98/BUILD.bazel" "$WORK/cv_b98_keyed"
printf '%s\n' 'hand_test(' '    name = "ex10_sweep",' '    args = [' '        "--case",' \
	'        "sweep",' '    ],' ')' 'hand_test(' '    name = "ex10_shapes",' \
	'    args = ["--case", "shapes"],' ')' 'hand_test(' '    name = "ex10_var",' '    args = [' \
	'        "--case",' '        WHICH,' '    ],' '    data = ["hidden"],' ')' 'hand_test(' \
	'    name = "ex10_inline",' '    args = ["--case", WHICH_TOO, "--x", "other"],' ')' \
	>> "$WORK/cv/c-piscine/c-piscine-c-98/BUILD.bazel"
printf 'What did the sweep find?\tsweep\nWhich shape?\tshapes\nWhat did it miss?\tswept\nWhere is it?\thidden\n' \
	>> "$_cv98/ex10/clues.tsv"
! st_mine || $CONV > "$WORK/cv.keyed" 2>&1
cv_dead_in() { grep -A6 -F -- "$1 names a case that does not exist" "$WORK/cv.keyed"; }
want_broken_none "conventions: a name a test passes as --case is a label" 'line 8: sweep' -- \
	cv_dead_in c-piscine/c-piscine-c-98/tests/ex10/clues.tsv
want_broken_none "conventions: ...and so is one on the line of its --case" 'line 9: shapes' -- \
	cv_dead_in c-piscine/c-piscine-c-98/tests/ex10/clues.tsv
want_out "conventions: ...while a name no test passes is not" 'line 10: swept' -- \
	cv_dead_in c-piscine/c-piscine-c-98/tests/ex10/clues.tsv
want_out "conventions: ...nor a word quoted after a --case that is no literal" 'line 11: hidden' -- \
	cv_dead_in c-piscine/c-piscine-c-98/tests/ex10/clues.tsv
cv_unread() { grep -A3 -F -- "passes --case a value this check cannot read" "$WORK/cv.keyed"; }
want_out "conventions: a --case value on the next line that is no literal is reported" \
	'        WHICH,' -- cv_unread
want_out "conventions: ...and one on its line" 'args = ["--case", WHICH_TOO' -- cv_unread
mv "$WORK/cv_ex10_keyed.tsv" "$_cv98/ex10/clues.tsv"
mv "$WORK/cv_b98_keyed" "$WORK/cv/c-piscine/c-piscine-c-98/BUILD.bazel"
rm -f "$WORK/cv.keyed"
cv_all_rows() { $CONV 2>&1 | grep -A8 -F -- "$1 has a first-red hint"; }
want_out "conventions: ...and so is one that far down keyed to a line" \
	'line 6 (no question)' -- cv_all_rows c-piscine/c-piscine-c-98/tests/ex10/clues.tsv
printf 'Line two prints a word.\tline 2\n' >> "$_cv98/ex11/clues.tsv"
want_broken_none "conventions: ...but not in a file that is no program's" \
	'line 4 (no question)' -- cv_all_rows c-piscine/c-piscine-c-98/tests/ex11/clues.tsv

# A hint that answers an overflow with a wider type (finding 060, WP-75):
# a diff legend's "the accumulator's type" and a clue asking for "a wider
# type" (both reported), and one asking whether the value has to be formed
# at all, beside a long string, which is no type (quiet). A diff hint wraps,
# so the phrase is found across a line end, in a readings target's legend
# too (ex35, reported, at the line it starts on); the question about every
# platform, wrapped the same way, is not (ex36).
mkdir -p "$_cv99/ex70" "$_cv99/ex71" "$_cv99/ex72" "$_cv99/ex35" "$_cv99/ex36"
printf '  The input is text.\n    * only long inputs  -> the accumulator%ss\n                           type\n' "'" \
	> "$_cv99/ex35/diff_clues_readings.txt"
printf '  The input is text.\n    * only long inputs  -> does every type the value passes\n                           through hold it on every platform?\n' \
	> "$_cv99/ex36/diff_clues.txt"
printf '  Text in, a number out.\n    * only long inputs  -> the accumulator%ss type\n' "'" \
	> "$_cv99/ex70/diff_clues.txt"
printf 'Which wider type holds the sum?\n' > "$_cv99/ex71/clues.tsv"
{
	printf '  Text in, a number out.\n'
	printf '    * only long inputs  -> every value fits an int: does anything computed on the\n'
	printf '                           way to it not fit? Is it held in a long string?\n'
} > "$_cv99/ex72/diff_clues.txt"
! st_mine || $CONV > "$WORK/cv.widen" 2>&1
want_out "conventions: a legend naming the accumulator's type is reported" \
	'c-99/tests/ex70/diff_clues.txt:2:' -- cat "$WORK/cv.widen"
want_out "conventions: ...and a clue asking for a wider type" \
	'c-99/tests/ex71/clues.tsv:1:' -- cat "$WORK/cv.widen"
want_broken_none "conventions: ...not one asking whether it has to be formed" \
	'c-99/tests/ex72/diff_clues.txt' -- cat "$WORK/cv.widen"
want_out "conventions: ...and a legend's phrase wrapped across a line end, in a readings legend" \
	'c-99/tests/ex35/diff_clues_readings.txt:2:' -- cat "$WORK/cv.widen"
want_out "conventions: ...named at the line it starts on, and the line it ends on" \
	"the accumulator's (wrapped onto line 3)" -- cat "$WORK/cv.widen"
want_broken_none "conventions: ...but not the question about every platform, wrapped" \
	'c-99/tests/ex36/diff_clues.txt' -- cat "$WORK/cv.widen"
rm -f "$WORK/cv.widen"

# A case's own hint file (clues_<x>.tsv) is held to the labels of the .txt
# files beside it, as clues.tsv is to expected.txt: a label no case has is a
# gate that never opens, and no check held these files' labels to a case.
mkdir -p "$_cv99/ex44" "$_cv99/ex45"
printf 'wide\t3\n' > "$_cv99/ex44/wide.txt"
printf 'What type is it?\twide\twdie\n' > "$_cv99/ex44/clues_wide.tsv"
printf 'wide\t3\n' > "$_cv99/ex45/wide.txt"
printf 'What type is it?\twide\n' > "$_cv99/ex45/clues_wide.tsv"
want_out "conventions: a per-case clue label with no case is reported" \
	'line 1: wdie' -- \
	$CONV
want_broken_none "conventions: ...and one whose case exists is not" \
	'c-99/tests/ex45/clues_wide.tsv names a case' -- \
	$CONV
# In a program's folder the rule above accepts a case's name, "line N" and
# "valgrind" in a clues_<x>.tsv, and this one must not report what it allows:
# the invented c_program of c-98 ex10, whose folder holds no .txt at all.
printf 'Which case is this?\ttwo\tvalgrind\tline 2\n' > "$_cv98/ex10/clues_args.tsv"
want_broken_none "conventions: ...nor a program's case names, lines and valgrind" \
	'c-98/tests/ex10/clues_args.tsv names a case' -- \
	$CONV
printf 'Which case is this?\ttow\n' > "$_cv98/ex10/clues_typo.tsv"
want_out "conventions: ...while a misspelt one there still is" \
	'c-98/tests/ex10/clues_typo.tsv names a case that no expected file' -- \
	$CONV
# The two rules read a program's folder, and one must not report what the
# other allows (V12): a labeled program case keys its hints to the labels of
# its rows (diff_output.sh puts a failing row's label beside the case's name),
# so a row of its .txt is a label in its own hint file and in clues.tsv. The
# invented case "one" of c-98 ex10 is labeled and expects a.txt; its row's
# label "wide" keys a clues_rows.tsv row and a clues.tsv row, and "wdie"
# names nothing in either. Case "two" is not labeled: its b.txt is a line
# the program prints, keyed "line 1", so its first field keys nothing in
# either file -- a hint keyed to it would never fire.
printf 'wide\t3\n' > "$_cv98/ex10/a.txt"
printf 'Printed words.\n' > "$_cv98/ex10/b.txt"
printf 'Which row is this?\twide\n' > "$_cv98/ex10/clues_rows.tsv"
want_broken_none "conventions: a labeled program case's row keys its own hint file" \
	'c-98/tests/ex10/clues_rows.tsv names a case' -- $CONV
printf 'Which line is this?\tPrinted words.\n' > "$_cv98/ex10/clues_printed.tsv"
want_out "conventions: ...an unlabeled case's line does not" \
	'c-98/tests/ex10/clues_printed.tsv names a case that no expected file' -- $CONV
cp "$_cv98/ex10/clues.tsv" "$WORK/cv_ex10_clues.tsv"
printf 'Which row is this?\twide\nWhich row is that?\twdie\nWhich line is this?\tPrinted words.\n' \
	>> "$_cv98/ex10/clues.tsv"
want_broken_none "conventions: ...and the program's clues.tsv" 'line 8: wide' -- \
	cv_dead c-piscine/c-piscine-c-98/tests/ex10/clues.tsv
want_out "conventions: ...where a label of no row is still reported" 'line 9: wdie' -- \
	cv_dead c-piscine/c-piscine-c-98/tests/ex10/clues.tsv
want_out "conventions: ...and so is an unlabeled case's line" 'line 10: Printed words.' -- \
	cv_dead c-piscine/c-piscine-c-98/tests/ex10/clues.tsv
rm -f "$_cv98/ex10/a.txt" "$_cv98/ex10/b.txt" "$_cv98/ex10/clues_rows.tsv" \
	"$_cv98/ex10/clues_printed.tsv"
mv "$WORK/cv_ex10_clues.tsv" "$_cv98/ex10/clues.tsv"

# ----------------------- conventions: legends, zeroed buffers, harness arrays
# A differential harness's column legend (finding 058): the diff layer reads
# the "Line:" paragraph of its header, so the sentence opens a comment line of
# its own within the first 12. One fixture per shape: on the /* line
# (reported), none at all (reported), the shape itself (quiet), and the
# sentence after other words on a line of its own (reported).
mkdir -p "$_cv99/ex40" "$_cv99/ex41" "$_cv99/ex42" "$_cv99/ex43"
printf '/* Harness for ft_x. Line: <hexA>\\t<n>. */\nint x;\n' > "$_cv99/ex40/diff_x.c"
printf '/* Harness for ft_x: reads records and reprints them. */\nint x;\n' \
	> "$_cv99/ex41/diff_x.c"
printf '/* Harness for ft_x.\n * Line: <hexA>\\t<n>\\t<returned int>. The input,\n * then the result. */\nint x;\n' \
	> "$_cv99/ex42/diff_x.c"
want_out "conventions: a Line: sentence on the /* line is reported" \
	'c-99/tests/ex40/diff_x.c: its "Line:" sentence is on the /* line' -- \
	$CONV
want_out "conventions: a harness with no Line: sentence is reported" \
	'c-99/tests/ex41/diff_x.c: no comment line in its first 12 begins with "Line:"' -- \
	$CONV
want_broken_none "conventions: a Line: line of its own is accepted" \
	'c-99/tests/ex42/diff_x.c' -- \
	$CONV
printf '/* Harness for ft_x.\n * Columns. Line: <hexA>\\t<n>. */\nint x;\n' \
	> "$_cv99/ex43/diff_x.c"
want_out "conventions: a Line: sentence after other words is reported" \
	'c-99/tests/ex43/diff_x.c: its "Line:" sentence does not begin its comment line' -- \
	$CONV

# A string harness's legend has a family line for the bytes above 0x7f
# (finding 061), or says why none reaches the code: one with neither
# (reported), one with the line, and one whose items only the harness reads,
# saying so in a maintainer's line (both quiet). What makes a string harness
# is that it decodes bytes with one of diffio's hex readers, whatever its
# header calls them: ex78's says "escaped bytes" and is held all the same,
# and a harness of numbers whose header names hex reads no byte (quiet).
# The legend is any diff_clues*.txt beside the harness: a readings target's
# diff_clues_readings.txt naming the family is enough (ex37, quiet), and a
# harness with no legend at all has none (ex38, reported).
mkdir -p "$_cv99/ex73" "$_cv99/ex74" "$_cv99/ex75" "$_cv99/ex76" "$_cv99/ex78" \
	"$_cv99/ex37" "$_cv99/ex38"
for _e in ex73 ex74 ex75 ex37 ex38; do
	printf '/* Harness for ft_x.\n * Line: <hexStr>\\t<n>. The string, two hex digits per byte. */\nint x;\nvoid r(char **f, size_t *n) { dio_unhex(f[0], n, 0); }\n' \
		> "$_cv99/$_e/diff_x.c"
done
printf '/* Harness for ft_y.\n * Line: <hexN>\\t<m>. Two ints, then the result. */\nint y;\n' > "$_cv99/ex76/diff_y.c"
# Past its first twelve lines, where the old rule read for the word.
{
	printf '/* Harness for ft_z.\n * Line: <s>\\t<n>. The strings, as escaped bytes.\n'
	printf ' *\n * (a header long enough that the code starts past line twelve)\n *\n *\n *\n *\n *\n *\n */\n'
	printf 'int z;\n\nvoid r(char *l, int *n) { dio_hex_list(l, n); }\n'
} > "$_cv99/ex78/diff_z.c"
printf '  One count per string.\n    * only long strings -> where the count stops\n' > "$_cv99/ex73/diff_clues.txt"
printf '  One count per string.\n    * only strings holding a byte of 0x80 or more -> how a char compares\n' \
	> "$_cv99/ex74/diff_clues.txt"
printf '# conventions: no byte family -- only the harness reads the items\n  One count per item.\n' \
	> "$_cv99/ex75/diff_clues.txt"
printf '  One sum per pair.\n' > "$_cv99/ex76/diff_clues.txt"
printf '  One count per list.\n    * only empty lists -> where the walk starts\n' > "$_cv99/ex78/diff_clues.txt"
printf '  One count per string.\n    * only long strings -> where the count stops\n' > "$_cv99/ex37/diff_clues.txt"
printf '  ex37_readings: one count per string.\n    * only strings holding a byte of 0x80 or more -> how a char compares\n' \
	> "$_cv99/ex37/diff_clues_readings.txt"
! st_mine || $CONV > "$WORK/cv.bytes" 2>&1
cv_bytes() { grep -A6 -F "a string harness's legend names no family" "$WORK/cv.bytes"; }
want_out "conventions: a string legend with no line for bytes above 0x7f is reported" \
	'c-99/tests/ex73/diff_x.c' -- cv_bytes
want_out "conventions: ...whatever its header calls the bytes" 'c-99/tests/ex78/diff_z.c' -- cv_bytes
want_out "conventions: ...and a string harness with no legend at all" 'c-99/tests/ex38/diff_x.c' -- cv_bytes
want_broken_none "conventions: ...not one with the line" 'c-99/tests/ex74/' -- cv_bytes
want_broken_none "conventions: ...nor one whose readings legend has it" 'c-99/tests/ex37/' -- cv_bytes
want_broken_none "conventions: ...nor one saying why no byte reaches the code" 'c-99/tests/ex75/' -- cv_bytes
want_broken_none "conventions: ...nor a harness of numbers" 'c-99/tests/ex76/' -- cv_bytes
rm -f "$WORK/cv.bytes"

# A differential harness that prints "untouched" for an out-parameter that
# kept its start: one starting value is one a corpus case can expect, so it
# starts from two (the wave 5 review: C 01 ex03's harness, which started at
# 0 and then at one other value). One toy per shape, read from one run: one
# preset (reported), two (quiet).
mkdir -p "$_cv99/ex62" "$_cv99/ex63"
_cv_pre_h='/* Harness for ft_x.\n * Line: <n>\t<out>. */\n#define PRESET_A 7\n'
_cv_pre_b='void ft_x(int *out);\nint main(void) { int o = PRESET_A; ft_x(&o); if (o == PRESET_A) printf("untouched"); return (0); }\n'
printf '%b' "$_cv_pre_h$_cv_pre_b" > "$_cv99/ex62/diff_x.c"
printf '%b' "$_cv_pre_h"'#define PRESET_B (-7)\n'"$_cv_pre_b" > "$_cv99/ex63/diff_x.c"
_cv_pre_out=""
! st_mine || _cv_pre_out=$($CONV 2>&1)
cv_pre_seen() { printf '%s\n' "$_cv_pre_out"; }
want_out "conventions: an untouched read from one starting value is reported" \
	'c-99/tests/ex62/diff_x.c reads a result as never written ("untouched") from fewer than two starting values' -- \
	cv_pre_seen
want_broken_none "conventions: ...and one from two is not" \
	'c-99/tests/ex63/diff_x.c reads a result as never written' -- cv_pre_seen
rm -rf "$_cv99/ex62" "$_cv99/ex63"

# A readings corpus's hint file names the level its exNN_readings target sits
# at -- _RAISED's, or strict -- and above strict calls its question a
# convention (the wave 5 review: C 11 ex06's corpus moved to robust beside
# C 06 ex03's, the same question, and its hint went on saying strict). One
# toy per shape, read from one run: raised, saying so (quiet); raised, still
# saying strict and "reading" (reported twice); at strict, calling itself a
# convention (reported); at strict, saying so (quiet).
cp "$WORK/cv/tools/defs.bzl" "$WORK/cv_defs_readings.bak"
printf '_RAISED = {\n    "c-piscine/c-piscine-c-99:ex64_readings": 3,\n    "c-piscine/c-piscine-c-99:ex65_readings": 3,\n}\n' \
	>> "$WORK/cv/tools/defs.bzl"
mkdir -p "$_cv99/ex64" "$_cv99/ex65" "$_cv99/ex66" "$_cv99/ex67"
printf '  ex64_readings: every case here holds a mark.\n    * any of them -> the subject never\n      reaches one; a convention this repo chose, at robust. How is a mark read?\n' \
	> "$_cv99/ex64/diff_clues_readings.txt"
printf '  ex65_readings: every case here holds a mark.\n    * any of them -> its reading, at\n      strict. How is a mark read?\n' \
	> "$_cv99/ex65/diff_clues_readings.txt"
printf '  ex66_readings: every case here holds a mark.\n    * any of them -> a convention this repo chose, at strict. How is a mark read?\n' \
	> "$_cv99/ex66/diff_clues_readings.txt"
printf '# ex67_readings, at robust once.\nHow is a mark read? This harness reads it one way, its reading, at strict.\tmark\n' \
	> "$_cv99/ex67/clues_readings.tsv"
_cv_rd_out=""
! st_mine || _cv_rd_out=$($CONV 2>&1)
cv_rd_seen() { printf '%s\n' "$_cv_rd_out"; }
want_broken_none "conventions: a raised readings hint saying its level and a convention is quiet" \
	'c-99/tests/ex64/diff_clues_readings.txt' -- cv_rd_seen
want_out "conventions: a raised readings hint that says strict is reported" \
	'c-99/tests/ex65/diff_clues_readings.txt says its target sits at strict, and ex65_readings sits at robust' -- \
	cv_rd_seen
want_out "conventions: ...and one that calls no convention" \
	'c-99/tests/ex65/diff_clues_readings.txt is the hint of ex65_readings, at robust, and does not call its question a convention' -- \
	cv_rd_seen
want_out "conventions: a convention at strict is reported" \
	'c-99/tests/ex66/diff_clues_readings.txt is the hint of ex66_readings, at strict, and calls its question a convention' -- \
	cv_rd_seen
want_broken_none "conventions: a reading at strict is quiet, its comment lines unread" \
	'c-99/tests/ex67/clues_readings.tsv says its target sits at' -- cv_rd_seen
cp "$WORK/cv_defs_readings.bak" "$WORK/cv/tools/defs.bzl"
rm -rf "$_cv99/ex64" "$_cv99/ex65" "$_cv99/ex66" "$_cv99/ex67"

# A zeroed buffer handed to the function under test (finding 057): C 03's
# appenders ran on calloc'd destinations, where the byte a terminator belongs
# in is 0 before the call and a missing one never shows. One fixture per
# shape: calloc'd and handed on (reported), the same with its reason written
# above it (quiet), a struct's nodes zeroed so their links are NULL (quiet),
# and an initialised array handed to a function the harness declares (reported).
mkdir -p "$_cv99/ex46" "$_cv99/ex47" "$_cv99/ex48" "$_cv99/ex49"
cat > "$_cv99/ex46/diff_x.c" <<'CV_ZERO'
/* Harness for ft_x.
 * Line: <hexA>\t<hexOut>. */
char	*ft_x(char *dest, char *src);

int	main(void)
{
	char	*buf;

	buf = calloc(16, 1);
	ft_x(buf, "ab");
	return (0);
}
CV_ZERO
cat > "$_cv99/ex47/diff_x.c" <<'CV_ZERO_SAID'
/* Harness for ft_x.
 * Line: <hexA>\t<hexOut>. */
char	*ft_x(char *dest, char *src);

int	main(void)
{
	char	*buf;

	/* conventions: zeroed -- the toy reads it and writes nothing */
	buf = calloc(16, 1);
	ft_x(buf, "ab");
	return (0);
}
CV_ZERO_SAID
cat > "$_cv99/ex48/diff_x.c" <<'CV_NODES'
/* Harness for ft_x.
 * Line: <n>\t<size>. */
int	ft_x(t_list *begin);

int	main(void)
{
	t_list	*blk;

	blk = calloc(4, sizeof(t_list));
	ft_x(blk);
	return (0);
}
CV_NODES
cat > "$_cv99/ex49/diff_x.c" <<'CV_ARRAY'
/* Harness for x_fill.
 * Line: <n>\t<hexOut>. */
void	x_fill(char *s, int n);

int	main(void)
{
	char	out[32] = "";

	x_fill(out, 3);
	return (0);
}
CV_ARRAY
want_out "conventions: a calloc'd buffer handed to ft_x is reported" \
	'line 9: buf (calloc) reaches ft_x() on line 10' -- \
	$CONV
want_broken_none "conventions: ...unless its reason is written above it" \
	'c-99/tests/ex47/diff_x.c hands' -- \
	$CONV
want_broken_none "conventions: zeroed nodes of a struct are not reported" \
	'c-99/tests/ex48/diff_x.c hands' -- \
