printf '%s\n' '#!/bin/sh' '. "${SHELL_CHECK_LIB:?}"' 'ck_require "g exists" test -f "$1"' \
	'mkdir -p repo' 'cd repo && git init -q' 'ck "g is not empty" test -s "$1"' 'ck_report' \
	> "$_cv99/ex27/check.sh"
printf '%s\n' '#!/bin/sh' '. "${SHELL_CHECK_LIB:?}"' 'ck_require "g exists" test -f "$1"' \
	'GIT_CONFIG_NOSYSTEM=1' 'HOME=$(mktemp -d)' 'export GIT_CONFIG_NOSYSTEM HOME' \
