} > "$WORK/cvo/oracle/src/toy.rs"
printf 'pub fn generate() {}\n' > "$WORK/cvo2/oracle/src/toy.rs"
printf 'hand_test(\n    name = "ex00_oracle_fixtures",\n    srcs = ["//tools:oracle_fixtures.sh"],\n    args = ["--fn", "held_fixtures"],\n)\n' \
