# A run that stopped before its verdict line says nothing about a rule, so it
# is a harness error (2) here, never a quiet pass for the absence arms.
cvi_rule() {  # cvi_rule TOY HEADLINE -- that rule's report, and the run's status
	awk -v h="$2" '/^  FAIL: / { on = index($0, h) > 0 } on' "$WORK/$1.out"
	grep -q '^conventions: FAIL' "$WORK/$1.out" && return 1
	grep -q '^conventions: OK' "$WORK/$1.out" && return 0
	return 2
}
