printf '# Toy\n\nSee [the guide](missing.md).\n' > "$WORK/cvsc/.github/toy.md"
for _f in .scratch/tilde.sh .devcontainer/tilde.sh .github/tilde.sh m/generators/ex00.sh m/tilde.sh; do
