# ------------------------------------------- conventions: 42's command registry
# Every run target of a BUILD file is named in tools/fortytwo/commands.tsv,
# and every label a row names is declared (conventions.sh, "EVERY RUN TARGET
# IS A 42 COMMAND"). cvq is a toy checkout with 42 in it: a tools target, a
# shell project's :generate, and the registry, taken through each state in
# plain code, so every shard sees the same tree.
mkdir -p "$WORK/cvq/tools/fortytwo" "$WORK/cvq/c-piscine/c-piscine-shell-90"
cv_submit "c-piscine/c-piscine-shell-90" > "$WORK/cvq/tools/submit.sh"
: > "$WORK/cvq/tools/42.sh"
printf '%s\n' 'sh_binary(name = "init", srcs = ["init.sh"])' \
	'sh_binary(name = "planted", srcs = ["planted.sh"])' > "$WORK/cvq/tools/BUILD.bazel"
printf '%s\n' 'sh_binary(' '    name = "generate",' '    srcs = ["//tools:generate.sh"],' ')' \
	> "$WORK/cvq/c-piscine/c-piscine-shell-90/BUILD.bazel"
CONVQ="env BUILD_WORKSPACE_DIRECTORY=$WORK/cvq $SH $TOOLS/conventions.sh"
want_out "conventions: a checkout with 42 and no registry is reported" \
	"tools/fortytwo/commands.tsv is missing" -- $CONVQ
cvq_rows() {
	printf 'init\t\t//tools:init\tstudent\tSet your login.\n'
	printf 'generate\t[project]\t//<project>:generate\tstudent\tWrite the deliverables.\n'
	printf '%s' "$1"
}
cvq_rows "" > "$WORK/cvq/tools/fortytwo/commands.tsv"
want_out "conventions: a run target no row names is reported" \
	"//tools:planted is a run target no row names" -- $CONVQ
cvq_rows "$(printf -- '-\t\t//tools:planted\tinternal\tNo command runs it, and this says why.')
" > "$WORK/cvq/tools/fortytwo/commands.tsv"
want_broken_none "conventions: ...and with an internal row, nothing is" \
	"commands.tsv and the BUILD files disagree" -- $CONVQ
cvq_rows "$(printf -- '-\t\t//tools:planted\tinternal\tWhy.\ngone\t\t//tools:gone\tstudent\tA renamed target.')
" > "$WORK/cvq/tools/fortytwo/commands.tsv"
want_out "conventions: a row naming a target nobody declares is reported" \
	"names //tools:gone, which tools/BUILD.bazel does not declare" -- $CONVQ
cvq_rows "$(printf -- '-\t\t//tools:planted\tinternal\tWhy.\nfmt\t\t//<project>:format\tstudent\tNo project has it.')
" > "$WORK/cvq/tools/fortytwo/commands.tsv"
want_out "conventions: ...and so is a project target no project declares" \
	"names //<project>:format, and no project declares :format" -- $CONVQ
cvq_rows "$(printf -- '-\t\t//tools:planted\tinternal\tWhy.\naudit\t\tsh tools/gone.sh\tstudent\tA script that moved.')
" > "$WORK/cvq/tools/fortytwo/commands.tsv"
want_out "conventions: ...and a script a row runs that is not there" \
	"runs sh tools/gone.sh, which is not there" -- $CONVQ
# 42 never passes Bazel a flag that costs a cache or an answer (conventions.sh,
# "42 NEVER PASSES BAZEL A FLAG"): one in code, the same word in a docstring,
# which may name it, and a row that runs bazel coverage.
printf '%s\n' 'ARGV = ["bazel", "test", "--watchfs"]' '"""--watchfs is never passed."""' \
	> "$WORK/cvq/tools/fortytwo/planted.py"
want_out "conventions: 42 passing Bazel a banned flag is reported" \
	'tools/fortytwo/planted.py:1: "--watchfs' -- $CONVQ
want_broken_none "conventions: ...a docstring naming it is not" \
	"tools/fortytwo/planted.py:2" -- $CONVQ
cvq_rows "$(printf -- '-\t\t//tools:planted\tinternal\tWhy.\ncov\t\tbazel coverage\tstudent\tNo.')
" > "$WORK/cvq/tools/fortytwo/commands.tsv"
want_out "conventions: ...and a row that runs bazel coverage is" \
	"tools/fortytwo/commands.tsv:4: bazel coverage" -- $CONVQ

# ------------------------------------------------------ 42's entry and installer
# tools/42.sh hands over to python3 -I and the checkout's main.py, or, with no
# python3 new enough, prints the Bazel command 42 would have run; and
# tools/fortytwo/install.sh writes the `42` shim that finds the checkout around
# the folder it is typed in. A toy checkout (MODULE.bazel and the two scripts)
# and a stand-in python3 that prints what it was given: nothing here runs 42's
# Python, which //tools/tests:fortytwo_test covers. "Outside any checkout" is
# /, because the folders above $WORK can be an execroot, which holds this
# repository's MODULE.bazel and tools/42.sh.
FT42="$WORK/ft42"
mkdir -p "$FT42/bin" "$FT42/ws/tools/fortytwo" "$FT42/ws/a/b" "$FT42/other/tools" \
	"$FT42/other/x" "$FT42/it's ws/tools/fortytwo" "$FT42/mine/.local/bin"
for _d in "$FT42/ws" "$FT42/other" "$FT42/it's ws"; do
	: > "$_d/MODULE.bazel"
	cp "$TOOLS/42.sh" "$_d/tools/42.sh"
done
cp "$TOOLS/fortytwo/install.sh" "$FT42/ws/tools/fortytwo/install.sh"
cp "$TOOLS/fortytwo/install.sh" "$FT42/it's ws/tools/fortytwo/install.sh"
cat > "$FT42/bin/python3" <<'FT42_PY'
#!/bin/sh
# A stand-in python3. A version check against a floor of 3.1x passes unless
# FT42_OLD is set, and any other check fails, so a check that no longer
# compares the version (or names an older floor) turns every arm red.
case "$1" in
	-c) case "$2" in
		*"sys.exit(sys.version_info < (3, 1"[0-9]"))"*) [ -z "${FT42_OLD:-}" ] ;;
		*) exit 3 ;;
	esac ;;
	--version) echo "Python 3.8.10" ;;
	*) echo "python3 $*"; echo "FT_WS=$FT_WS"; echo "FT_CWD=$FT_CWD" ;;
esac
FT42_PY
chmod +x "$FT42/bin/python3"
printf '#!/bin/sh\necho mine\n' > "$FT42/mine/.local/bin/42"
# ft42_in DIR CMD... -- CMD in DIR, with the stand-in python3 first on PATH
# and none of `bazel run`'s variables, which 42.sh would take over $0's folder.
ft42_in() {
	(cd "$1" && shift && unset BUILD_WORKSPACE_DIRECTORY BUILD_WORKING_DIRECTORY &&
		PATH="$FT42/bin:$PATH" "$@")
}
want_out "42.sh: hands over to python3 -I and the checkout's main.py" \
	"python3 -I $FT42/ws/tools/fortytwo/main.py test ex03" -- \
	ft42_in "$FT42/ws/a/b" $SH "$FT42/ws/tools/42.sh" test ex03
want_out "42.sh: ...and passes the folder it was typed in" \
	"FT_CWD=$FT42/ws/a/b" -- ft42_in "$FT42/ws/a/b" $SH "$FT42/ws/tools/42.sh"
want_broken "42.sh: an old python3 is refused, and named" \
	"this machine has Python 3.8.10" -- \
	ft42_in "$FT42/ws" env FT42_OLD=1 $SH "$FT42/ws/tools/42.sh"
want_broken "42.sh: ...with the Bazel command that does without it" \
	"--test_tag_filters=lvl_basic,-manual 2>&1 | sh tools/first_red.sh" -- \
	ft42_in "$FT42/ws" env FT42_OLD=1 $SH "$FT42/ws/tools/42.sh"
want_out "install.sh: writes the shim" \
	"42: installed $FT42/home/.local/bin/42" -- \
	env HOME="$FT42/home" $SH "$FT42/ws/tools/fortytwo/install.sh"
want_green "install.sh: ...marked as its own" -- \
	grep -qF "# 42 shim, written by tools/fortytwo/install.sh" "$FT42/home/.local/bin/42"
want_out "shim: runs the checkout around the folder it is typed in" \
	"FT_WS=$FT42/other" -- ft42_in "$FT42/other/x" "$FT42/home/.local/bin/42" help
want_out "shim: ...and outside any, the checkout that installed it" \
	"FT_WS=$FT42/ws" -- ft42_in / "$FT42/home/.local/bin/42" help
want_green "install.sh: run again, it rewrites the shim and nothing else" -- \
	sh -c 'HOME="$1" '"$SH"' "$2" > /dev/null && [ "$(ls -A "$1/.local/bin")" = 42 ]' \
	_ "$FT42/home" "$FT42/ws/tools/fortytwo/install.sh"
want_out "install.sh: a 42 it did not write is left alone" \
	"is not 42's shim -- left alone" -- \
	env HOME="$FT42/mine" $SH "$FT42/ws/tools/fortytwo/install.sh"
want_green "install.sh: ...untouched" -- \
	sh -c '[ "$(cat "$1")" = "$(printf "#!/bin/sh\necho mine")" ]' _ "$FT42/mine/.local/bin/42"
env HOME="$FT42/q" $SH "$FT42/it's ws/tools/fortytwo/install.sh" > /dev/null 2>&1
want_out "shim: a checkout with a quote in its path falls back intact" \
	"FT_WS=$FT42/it's ws" -- ft42_in / "$FT42/q/.local/bin/42"

# ------------------------------------------------------------------ allocfail
# The layer that makes malloc say no, one allocation at a time. Both directions
# matter more than usual here, because the whole point is a branch that nothing
# else in the repo has ever executed: a version that reds everything would be
# indistinguishable from a working one on the only exercise it is wired to.
cat > "$WORK/af_good.c" <<'AF_GOOD'
#include <stdlib.h>

void	*af_target(void)
{
	char	*p;

	p = malloc(16);
	if (!p)
		return (NULL);
	p[0] = 'x';
	return (p);
}
AF_GOOD
cat > "$WORK/af_bad.c" <<'AF_BAD'
#include <stdlib.h>

void	*af_target(void)
{
	char	*p;

	p = malloc(16);
	p[0] = 'x';
	return (p);
}
AF_BAD
cat > "$WORK/af_case.c" <<'AF_CASE'
void	*af_target(void);

void	*af_case(void)
{
	return (af_target());
}
AF_CASE

want_green "allocfail: checking malloc's answer survives a refusal" -- \
	"$SH" "$TOOLS/allocfail_check.sh" $BUILD_PIN --src "$WORK/af_good.c" \
		--harness "$WORK/af_case.c" --shim "$TOOLS/allocfail_shim.c" --label af_good
want_red   "allocfail: using the pointer regardless is caught" -- \
	"$SH" "$TOOLS/allocfail_check.sh" $BUILD_PIN --src "$WORK/af_bad.c" \
		--harness "$WORK/af_case.c" --shim "$TOOLS/allocfail_shim.c" --label af_bad
# The probe is built with the pinned clang-12 and ld.bfd: it took `cc` from
# the box, then gcc, clang, clang-12 or gcc-10 (TO VERIFY V38).
want_broken "allocfail: --src and no --cc refuses, never takes the box's" \
	'--cc is required with --src' -- \
	"$SH" "$TOOLS/allocfail_check.sh" --src "$WORK/af_good.c" \
		--harness "$WORK/af_case.c" --shim "$TOOLS/allocfail_shim.c" --label af_good
# PAST --max-inject THE SWEEP SAMPLES, TO THE LAST REQUEST. A function that
# allocates through its input checks its first requests and not its last:
# refusing only the first --max-inject never reached it, and the layer said
# "PASS (partial)" over the one unguarded call. af_last_bad's twentieth
# request is used unchecked; with a budget of six, the sweep has to reach it.
cat > "$WORK/af_last_bad.c" <<'AF_LAST'
#include <stdlib.h>

void	*af_target(void)
{
	char	*p[20];
	int		i;

	i = 0;
	while (i < 19)
	{
		p[i] = malloc(8);
		if (!p[i])
		{
			while (--i >= 0)
				free(p[i]);
			return (NULL);
		}
		i++;
	}
	p[19] = malloc(8);
	p[19][0] = 'x';
	while (--i >= 0)
		free(p[i]);
	return (p[19]);
}
AF_LAST
want_red   "allocfail: past --max-inject, the sweep samples to the last request" -- \
	env ALLOCFAIL_MAX=6 "$SH" "$TOOLS/allocfail_check.sh" $BUILD_PIN --src "$WORK/af_last_bad.c" \
		--harness "$WORK/af_case.c" --shim "$TOOLS/allocfail_shim.c" --label af_last_bad
want_out   "allocfail: ...and says which it refused" 'then spread evenly to the last' -- \
	env ALLOCFAIL_MAX=6 "$SH" "$TOOLS/allocfail_check.sh" $BUILD_PIN --src "$WORK/af_last_bad.c" \
		--harness "$WORK/af_case.c" --shim "$TOOLS/allocfail_shim.c" --label af_last_bad
# THE SENTENCE IT APPLIES comes from the call site (--rule, a file the macro
# writes, as valgrind_test.sh's --rule is), and is the only one the report
# quotes; with none, it quotes none. It used to send every exercise to "if an
# error occurs", which one subject says (finding 082).
printf 'Toy, p.5: "Return NULL when memory runs out."\n' > "$WORK/af_contract.txt"
: > "$WORK/af_contract_empty.txt"
want_out   "allocfail: the FAIL quotes the call site's sentence" \
	'Toy, p.5: "Return NULL when memory runs out."' -- \
	"$SH" "$TOOLS/allocfail_check.sh" $BUILD_PIN --src "$WORK/af_bad.c" --rule "$WORK/af_contract.txt" \
		--harness "$WORK/af_case.c" --shim "$TOOLS/allocfail_shim.c" --label af_bad
want_broken_none "allocfail: ...and without one, quotes nothing" 'call site in BUILD.bazel' -- \
	"$SH" "$TOOLS/allocfail_check.sh" $BUILD_PIN --src "$WORK/af_bad.c" \
		--harness "$WORK/af_case.c" --shim "$TOOLS/allocfail_shim.c" --label af_bad
want_broken_none "allocfail: ...nor a sentence of another subject" 'if an error occurs' -- \
	"$SH" "$TOOLS/allocfail_check.sh" $BUILD_PIN --src "$WORK/af_bad.c" \
		--harness "$WORK/af_case.c" --shim "$TOOLS/allocfail_shim.c" --label af_bad
# Nor does its closing text say what "no subject" asks: whether one does is
# the call site's to say, and the runner cannot know (finding 082).
want_broken_none "allocfail: ...nor what no subject asks" 'No subject here' -- \
	"$SH" "$TOOLS/allocfail_check.sh" $BUILD_PIN --src "$WORK/af_bad.c" --rule "$WORK/af_contract.txt" \
		--harness "$WORK/af_case.c" --shim "$TOOLS/allocfail_shim.c" --label af_bad
want_broken "allocfail: an empty --rule file is refused" 'no sentence in --rule' -- \
	"$SH" "$TOOLS/allocfail_check.sh" $BUILD_PIN --src "$WORK/af_bad.c" --rule "$WORK/af_contract_empty.txt" \
		--harness "$WORK/af_case.c" --shim "$TOOLS/allocfail_shim.c" --label af_bad
want_broken "allocfail: a --rule file that is not there is refused" 'no sentence in --rule' -- \
	"$SH" "$TOOLS/allocfail_check.sh" $BUILD_PIN --src "$WORK/af_bad.c" --rule "$WORK/af_no_such_rule.txt" \
		--harness "$WORK/af_case.c" --shim "$TOOLS/allocfail_shim.c" --label af_bad
# AN ERROR THAT IS A VALUE (finding 075). A function whose subject reports the
# error as -1 goes through a harness that turns -1 into NULL and anything else
# into a sentinel pointer -- and the report said "still returned a pointer"
# about a function that had returned 0. The harness now says in words what
# the call returned (af_note), and the row is WRONG-RET, with those words.
cat > "$WORK/af_int_bad.c" <<'AF_INT_BAD'
#include <stdlib.h>

int	af_fill(int **out)
{
	*out = malloc(4 * sizeof(int));
	if (!*out)
		return (0);
	return (4);
}
AF_INT_BAD
cat > "$WORK/af_int_good.c" <<'AF_INT_GOOD'
#include <stdlib.h>

int	af_fill(int **out)
{
	*out = malloc(4 * sizeof(int));
	if (!*out)
		return (-1);
	return (4);
}
AF_INT_GOOD
cat > "$WORK/af_int_case.c" <<'AF_INT_CASE'
#include <stdio.h>

extern const char	*af_note;
static int			g_not_reported;
static char			g_note[64];

int	af_fill(int **out);

void	*af_case(void)
{
	int	*p;
	int	n;

	p = 0;
	n = af_fill(&p);
	if (n == -1)
		return (0);
	snprintf(g_note, sizeof(g_note), "returned %d, not -1", n);
	af_note = g_note;
	if (p)
		return (p);
	return (&g_not_reported);
}
AF_INT_CASE
want_red   "allocfail: a wrong value returned on a refusal is caught" -- \
	"$SH" "$TOOLS/allocfail_check.sh" $BUILD_PIN --src "$WORK/af_int_bad.c" \
		--harness "$WORK/af_int_case.c" --shim "$TOOLS/allocfail_shim.c" --label af_int_bad
want_out   "allocfail: ...as WRONG-RET, with the value it returned" \
	'WRONG-RET  allocation #1 failed, and it returned 0, not -1' -- \
	"$SH" "$TOOLS/allocfail_check.sh" $BUILD_PIN --src "$WORK/af_int_bad.c" \
		--harness "$WORK/af_int_case.c" --shim "$TOOLS/allocfail_shim.c" --label af_int_bad
want_broken_none "allocfail: ...never as a pointer it did not return" 'returned a pointer' -- \
	"$SH" "$TOOLS/allocfail_check.sh" $BUILD_PIN --src "$WORK/af_int_bad.c" \
		--harness "$WORK/af_int_case.c" --shim "$TOOLS/allocfail_shim.c" --label af_int_bad
want_green "allocfail: the error value the harness reads as NULL passes" -- \
	"$SH" "$TOOLS/allocfail_check.sh" $BUILD_PIN --src "$WORK/af_int_good.c" \
		--harness "$WORK/af_int_case.c" --shim "$TOOLS/allocfail_shim.c" --label af_int_good
# The note is the rest of the report line, after the counts the leak target
# added (live=, bytes=): a note whose own words look like a field is never
# read as one. Read greedily, "seen=9 result=null" in a note made this wrong
# value a green "returned NULL".
sed 's/"returned %d, not -1"/"returned %d, seen=9 result=null live=3"/' \
	"$WORK/af_int_case.c" > "$WORK/af_int_case_words.c"
want_red   "allocfail: a note's words are never read as the report's fields" -- \
	"$SH" "$TOOLS/allocfail_check.sh" $BUILD_PIN --src "$WORK/af_int_bad.c" \
		--harness "$WORK/af_int_case_words.c" --shim "$TOOLS/allocfail_shim.c" --label af_int_bad
want_out   "allocfail: ...and the row quotes the note whole" \
	'WRONG-RET  allocation #1 failed, and it returned 0, seen=9 result=null live=3' -- \
	"$SH" "$TOOLS/allocfail_check.sh" $BUILD_PIN --src "$WORK/af_int_bad.c" \
		--harness "$WORK/af_int_case_words.c" --shim "$TOOLS/allocfail_shim.c" --label af_int_bad

# --leaks (finding 084): what a function leaves allocated on a run that
# reported the error, judged by its own target at robust. Two toys that take a
# pair of blocks and report a refused second one; af_drop forgets the first,
# af_tidy hands it back. The basic sweep stays green on both -- it does not ask
# -- and says on that PASS what it did not ask. A toy that does not report the
# error is the basic sweep's finding and NOT JUDGED here, so it is not red
# twice; a toy whose every run fails to report leaves nothing to judge.
for _af in drop tidy; do
	{
		printf '#include <stdlib.h>\n\nvoid\t*af_target(void)\n{\n'
		printf '\tchar\t**pair;\n\n\tpair = malloc(2 * sizeof(char *));\n'
		printf '\tif (!pair)\n\t\treturn (NULL);\n\tpair[0] = malloc(4);\n'
		printf '\tpair[1] = malloc(4);\n\tif (!pair[0] || !pair[1])\n\t{\n'
		[ "$_af" = drop ] || printf '\t\tfree(pair[0]);\n\t\tfree(pair[1]);\n\t\tfree(pair);\n'
		printf '\t\treturn (NULL);\n\t}\n\treturn (pair);\n}\n'
	} > "$WORK/af_$_af.c"
done
af_leaks() {  # af_leaks TOY [--leaks]
	_t=$1; shift
	env -u NO_SKIP "$SH" "$TOOLS/allocfail_check.sh" $BUILD_PIN --src "$WORK/af_$_t.c" \
		--harness "$WORK/af_case.c" --shim "$TOOLS/allocfail_shim.c" --label "af_$_t" "$@"
}
want_green "allocfail: a leak on the error path is not the basic sweep's" -- af_leaks drop
want_out   "allocfail: ...whose PASS says what it did not ask" \
	'What this layer does NOT ask' -- af_leaks drop
want_red   "allocfail --leaks: a block left on the error path is red" -- af_leaks drop --leaks
want_out   "allocfail --leaks: ...and the row says what was left" \
	'block(s), ' -- af_leaks drop --leaks
want_green "allocfail --leaks: releasing it all is green" -- af_leaks tidy --leaks
want_out   "allocfail --leaks: ...and its PASS says whose rule it is" \
	"Whose rule this is: the repo's" -- af_leaks tidy --leaks
# af_mute is refused and hands back a pointer of its own instead of NULL:
# the basic sweep's NOT-NULL, and not this target's to judge.
printf '#include <stdlib.h>\n\nvoid\t*af_target(void)\n{\n\tstatic char\tnone[1];\n\tchar\t\t*p;\n\n\tp = malloc(16);\n\tif (!p)\n\t\treturn (none);\n\tp[0] = 0;\n\treturn (p);\n}\n' \
	> "$WORK/af_mute.c"
want_out   "allocfail --leaks: a run that did not report is not judged" \
	'NOT-JUDGED' -- af_leaks mute --leaks
want_green "allocfail --leaks: ...so nothing judged is a skip" -- af_leaks mute --leaks
want_red   "allocfail --leaks: ...which NO_SKIP=1 makes red" -- \
	env NO_SKIP=1 "$SH" "$TOOLS/allocfail_check.sh" $BUILD_PIN --src "$WORK/af_mute.c" \
		--harness "$WORK/af_case.c" --shim "$TOOLS/allocfail_shim.c" --label af_mute --leaks
want_red   "allocfail --leaks: a crash on the error path still fails" -- af_leaks bad --leaks

# --bin: a PROGRAM, whose own main() runs (finding 150). The toy keeps a copy
# of each argument and reports a refused copy on stderr; MODE_* builds the
# variants: one that checks and tidies, one that never looks at malloc's
# answer, one that checks and keeps what it had, one that stops answering.
# Linked as c_program links exNN_bin_allocfail: beside allocfail_program.c,
# with malloc and free wrapped.
cat > "$WORK/afp.c" <<'AF_PROG'
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

int	main(int ac, char **av)
{
	char	**keep;
	int		i;

	keep = malloc(sizeof(char *) * (size_t)ac);
	if (!keep)
		return (1);
	i = 1;
	while (i < ac)
	{
		keep[i] = malloc(strlen(av[i]) + 1);
		if (MODE_CHECK && !keep[i])
		{
			write(2, "no memory\n", 10);
			while (MODE_TIDY && --i >= 1)
				free(keep[i]);
			if (MODE_TIDY)
				free(keep);
			while (MODE_HANG)
				;
			return (1);
		}
		strcpy(keep[i], av[i]);
		i++;
	}
	while (--i >= 1)
		free(keep[i]);
	free(keep);
	return (0);
}
AF_PROG
for _v in good:1:1:0 bad:0:1:0 keep:1:0:0 stuck:1:1:1; do
	IFS=: read -r _n _c _t _h <<AF_V
$_v
AF_V
	"$CC" -w -DMODE_CHECK="$_c" -DMODE_TIDY="$_t" -DMODE_HANG="$_h" -o "$WORK/afp_$_n" \
		"$WORK/afp.c" "$TOOLS/allocfail_program.c" -Wl,--wrap=malloc -Wl,--wrap=free 2>/dev/null
done
printf 'int\tmain(void)\n{\n\treturn (0);\n}\n' > "$WORK/afp_none.c"
"$CC" -w -o "$WORK/afp_none" "$WORK/afp_none.c" "$TOOLS/allocfail_program.c" \
	-Wl,--wrap=malloc -Wl,--wrap=free 2>/dev/null
afp() {  # afp TOY [FLAG...] -- the toy program on three arguments
	_t=$1; shift
	"$SH" "$TOOLS/allocfail_check.sh" --bin "$WORK/afp_$_t" --label "afp_$_t" "$@" -- aa bb cc
}
want_green "allocfail --bin: a program that checks and stops is green" -- afp good
want_red   "allocfail --bin: one that uses a refused block is red" -- afp bad
want_out   "allocfail --bin: ...and the row names the signal" 'CRASH' -- afp bad
want_red   "allocfail --bin: one that never ends after a refusal is red" -- \
	env ALLOCFAIL_TIMEOUT=2 "$SH" "$TOOLS/allocfail_check.sh" --bin "$WORK/afp_stuck" \
		--label afp_stuck -- aa bb cc
want_green "allocfail --bin: what it printed and returned is not judged" -- afp keep
want_red   "allocfail --bin --leaks: a block held at exit is red" -- afp keep --leaks
want_out   "allocfail --bin --leaks: ...and the row says what was held" \
	'still allocated at exit' -- afp keep --leaks
want_green "allocfail --bin --leaks: releasing it all is green" -- afp good --leaks
want_green "allocfail --bin: asking for no memory passes, under NO_SKIP too" -- \
	env NO_SKIP=1 "$SH" "$TOOLS/allocfail_check.sh" --bin "$WORK/afp_none" --label afp_none
# ...but is not headed OK: nothing was refused, so nothing was checked, and a
# green that reads like a verdict is the shape design.md ranks worst.
want_out   "allocfail --bin: ...headed NOTHING TO REFUSE" 'NOTHING TO REFUSE' -- \
	env NO_SKIP=1 "$SH" "$TOOLS/allocfail_check.sh" --bin "$WORK/afp_none" --label afp_none
want_broken_none "allocfail --bin: ...and never OK" 'allocfail_check: OK' -- \
	env NO_SKIP=1 "$SH" "$TOOLS/allocfail_check.sh" --bin "$WORK/afp_none" --label afp_none

# THE CASE'S RUN, AND ITS GATE'S. A case can hand the program more arguments
# in a file and run it as ./NAME from a folder holding files of its own
# (c_program's argv_file and cwd_files); the sweep runs it that way, and its
# gate too. Rush 02's one-argument case runs beside numbers.dict, and its sweep
# ran from a folder with no dictionary: the gate was red on every correct
# program and SKIPped, and under NO_SKIP=1 only the missing-dictionary path's
# requests were refused. The toy asks for memory only where toy.cfg is beside
# it, and prints whether it found it.
cat > "$WORK/afp_beside.c" <<'AF_BESIDE'
#include <fcntl.h>
#include <stdlib.h>
#include <unistd.h>

int	main(void)
{
	char	*p;
	int		fd;

	fd = open("toy.cfg", O_RDONLY);
	if (fd < 0)
	{
		write(1, "none\n", 5);
		return (0);
	}
	close(fd);
	p = malloc(4);
	if (!p)
		return (1);
	free(p);
	write(1, "found\n", 6);
	return (0);
}
AF_BESIDE
"$CC" -w -o "$WORK/afp_beside" "$WORK/afp_beside.c" "$TOOLS/allocfail_program.c" \
	-Wl,--wrap=malloc -Wl,--wrap=free 2>/dev/null
"$CC" -w -o "$WORK/afp_beside_plain" "$WORK/afp_beside.c" 2>/dev/null
printf 'found\n' > "$WORK/afp_found.txt"
printf 'a toy file\n' > "$WORK/afp_cfg.txt"
printf 'dd\nee\n' > "$WORK/afp_more.argv"
afp_beside() {  # afp_beside [FLAG...] -- the toy, gated on its own case
	env -u NO_SKIP "$SH" "$TOOLS/allocfail_check.sh" --bin "$WORK/afp_beside" --label afp_beside \
		--gate-differ "$TOOLS/diff_output.sh" --gate-bin "$WORK/afp_beside_plain" \
		--gate-expected "$WORK/afp_found.txt" "$@" --
}
want_out   "allocfail --bin --run-as: the sweep runs from the case's folder" \
	'It asks for memory 1 time(s)' -- \
	afp_beside --run-as toy --cwd-file "toy.cfg=$WORK/afp_cfg.txt"
want_out   "allocfail --bin --run-as: ...and says where it ran" \
	'toy.cfg  a copy of' -- \
	afp_beside --run-as toy --cwd-file "toy.cfg=$WORK/afp_cfg.txt" --show-run bazel-bin/toy
want_out   "allocfail --bin: without the folder, its gate is red" 'SKIP' -- afp_beside
want_broken "allocfail --bin: --cwd-file without --run-as is refused" \
	'--cwd-file stages a file' -- afp_beside --cwd-file "toy.cfg=$WORK/afp_cfg.txt"
want_broken "allocfail: a function's probe takes no run folder" \
	"a function's probe takes none" -- \
	"$SH" "$TOOLS/allocfail_check.sh" $BUILD_PIN --src "$WORK/af_good.c" --harness "$WORK/af_case.c" \
		--shim "$TOOLS/allocfail_shim.c" --label af_good --run-as toy
want_out   "allocfail --bin --argv-file: the file's arguments follow the others" \
	'It asks for memory 6 time(s)' -- afp good --argv-file "$WORK/afp_more.argv"

# WHOSE RULE: the call site's, never the runner's. The runner used to print
# one subject's "handle errors coherently" under every program's verdict, C
# 10's included, whose subject has no such sentence. Without --rule it quotes
# no subject; with one it prints that, and only that -- the same --rule FILE a
# function's sweep takes (the arms above), so the two modes agree.
printf '%s\n' 'A TOY RULE, ITS OWN WORDS' > "$WORK/afp_rule.txt"
want_broken_none "allocfail --bin: no --rule, no subject's sentence" 'coherently' -- afp good
want_broken_none "allocfail --bin: ...and no rule heading" 'call site in BUILD.bazel' -- afp good
want_out   "allocfail --bin: --rule is printed under a PASS" 'A TOY RULE, ITS OWN WORDS' -- \
	afp good --rule "$WORK/afp_rule.txt"
want_out   "allocfail --bin: ...and under a FAIL" 'A TOY RULE, ITS OWN WORDS' -- \
	afp bad --rule "$WORK/afp_rule.txt"
want_out   "allocfail --bin --leaks: ...and under the leak target's verdict" 'A TOY RULE, ITS OWN WORDS' -- \
	afp good --leaks --rule "$WORK/afp_rule.txt"

# THE WIRING, proven before anything is judged. A program whose report says
# the shim's own probe was not counted (wrapped=0) was linked without the
# wraps: no refusal could reach it, so "asked for no memory" would be a lie.
# And the control run at K+1, which cannot refuse anything, must end as the
# plain run did, or the sweep is not repeatable. Both are the harness's
# faults (exit 2). Shell toys that write the shim's report line themselves.
printf '#!/bin/sh\nprintf "\\nAF_RESULT arm=%%s seen=0 result=exit live=0 bytes=0 wrapped=0\\n" "${AF_ARM:-0}" > "$AF_REPORT"\n' \
	> "$WORK/afp_unwrapped"
printf '#!/bin/sh\na=${AF_ARM:-0}\nprintf "\\nAF_RESULT arm=%%s seen=2 result=exit live=0 bytes=0 wrapped=1\\n" "$a" > "$AF_REPORT"\n[ "$a" -eq 3 ] && exit 5\nexit 0\n' \
	> "$WORK/afp_drifts"
chmod +x "$WORK/afp_unwrapped" "$WORK/afp_drifts"
want_broken "allocfail --bin: a link without the wraps refuses" \
	'was not linked with' -- afp unwrapped
want_broken "allocfail --bin: a control run that ends differently refuses" \
	'control run is not trustworthy' -- afp drifts

# --leaks needs a plain run that holds nothing: what an error path leaves can
# only be told apart from that. A program that keeps a block on every run
# skips, and NO_SKIP=1 makes that red.
printf '#include <stdlib.h>\n\nint\tmain(void)\n{\n\tchar\t*p;\n\n\tp = malloc(8);\n\tif (!p)\n\t\treturn (1);\n\tp[0] = 0;\n\treturn (p[0]);\n}\n' \
	> "$WORK/afp_holds.c"
"$CC" -w -o "$WORK/afp_holds" "$WORK/afp_holds.c" "$TOOLS/allocfail_program.c" \
	-Wl,--wrap=malloc -Wl,--wrap=free 2>/dev/null
want_out   "allocfail --bin --leaks: a plain run that holds a block skips" \
	'already' -- env -u NO_SKIP "$SH" "$TOOLS/allocfail_check.sh" --bin "$WORK/afp_holds" \
		--label afp_holds --leaks
want_red   "allocfail --bin --leaks: ...which NO_SKIP=1 makes red" -- \
	env NO_SKIP=1 "$SH" "$TOOLS/allocfail_check.sh" --bin "$WORK/afp_holds" \
		--label afp_holds --leaks

# THE COUNT IS EXACT however many blocks are live at once. The counter's
# table was a fixed 4096 slots, and past it the count was "untracked" for
# good: a program that held 5000 blocks and freed every one was reported as
# holding an unknown number, and --leaks skipped it -- red under NO_SKIP=1.
# A toy that keeps 5000 blocks, frees them all, and tidies on a refusal.
cat > "$WORK/afp_many.c" <<'AF_MANY'
#include <stdlib.h>

int	main(void)
{
	void	**p;
	int		i;

	p = malloc(sizeof(void *) * 5000);
	if (!p)
		return (1);
	i = 0;
	while (i < 5000)
	{
		p[i] = malloc(1);
		if (!p[i])
		{
			while (--i >= 0)
				free(p[i]);
			free(p);
			return (1);
		}
		i++;
	}
	while (--i >= 0)
		free(p[i]);
	free(p);
	return (0);
}
AF_MANY
"$CC" -w -o "$WORK/afp_many" "$WORK/afp_many.c" "$TOOLS/allocfail_program.c" \
	-Wl,--wrap=malloc -Wl,--wrap=free 2>/dev/null
want_green "allocfail --bin --leaks: 5000 live blocks, all freed, is clean" -- \
	env NO_SKIP=1 ALLOCFAIL_MAX=8 "$SH" "$TOOLS/allocfail_check.sh" --bin "$WORK/afp_many" \
		--label afp_many --leaks
want_out   "allocfail --bin: a long count is sampled to the last request" \
	'spread to the last' -- \
	env ALLOCFAIL_MAX=4 "$SH" "$TOOLS/allocfail_check.sh" --bin "$WORK/afp_good" \
		--label afp_good -- a b c d e f g h i j
want_broken "allocfail --bin: a program and a function probe at once is refused" \
	'Not both' -- "$SH" "$TOOLS/allocfail_check.sh" --bin "$WORK/afp_good" \
		--src "$WORK/af_good.c" --harness "$WORK/af_case.c"

# ------------------------------------------------------------------ stub_check
# The one runner here whose failure is not a red exercise but a PUBLISHED answer.
# stub_check.sh is what stands between the owner's finished work and the template
# branch other people clone, and it has already failed once in exactly the way
# this file exists to catch: it globbed `*/deliverable/*.c`, so it printed
# "OK — all 123 deliverable(s) are stubs" over a tree in which c-08's four
# answers were sitting untouched, because c-08's deliverable IS a header. Those
# four shipped. So did rush-00's rush.h with one team's whole data model in it,
# and all 18 shell generators, for the same reason: a check that reports on the files
# it happens to look at says nothing about the ones it does not.
#
# Hence one green and one red per KIND, rather than a couple of representative
# cases — the failure mode being guarded against is a whole kind falling out of
# scope, which a passing arm on a neighbouring kind would not notice. The reds
# have the real published SHAPES — a function-like macro, and a lone prototype,
# which is what c-08 ex00 through ex03 each turn in. The fixtures deliberately do
# NOT reproduce those answers: this file ships on the template, so a fixture that
# quoted one would hand it over through the very test that exists to stop it.
# SQUARE and ft_selftest_len are not exercises anywhere in this repo.
#
# --file is used instead of the repo mode because repo mode is built on
# `git ls-files`, and a self-test that needs a populated git repository is one
# that will not run hermetically.
mkdir -p "$WORK/sc"
SC_H='/* ************************************************************************** */
/*                                        stub_check selftest fixture           */
/* ************************************************************************** */'
printf '%s\n\n#ifndef FT_ABS_H\n# define FT_ABS_H\n\n#endif\n' "$SC_H" > "$WORK/sc/guards.h"
printf '%s\n\n#ifndef SC_MACRO_H\n# define SC_MACRO_H\n# define SQUARE(n) ((n) * (n))\n#endif\n' \
	"$SC_H" > "$WORK/sc/macro.h"
printf '%s\n\n#ifndef SC_PROTO_H\n# define SC_PROTO_H\n\nint\tft_selftest_len(char *str);\n\n#endif\n' \
	"$SC_H" > "$WORK/sc/proto.h"
# The "real" fixtures are real CODE and deliberately no exercise's answer: the
# selftest ships in the public template, and a known-bad fixture copied from a
# deliverable is an answer in a file anyone can open. A made-up function, a
# made-up program name and a made-up command do the same job.
cat > "$WORK/sc/stub.c" <<'SC_STUB'
int	ft_selftest_twice(int n)
{
	(void)n;
	return (0);
}
SC_STUB
cat > "$WORK/sc/answer.c" <<'SC_REAL'
int	ft_selftest_twice(int n)
{
	return (n + n);
}
SC_REAL
printf 'NAME = selftest_prog\n\nall:\n\t@echo "TODO: build $(NAME)"\n' > "$WORK/sc/Makefile"
mkdir -p "$WORK/sc/real"
printf 'NAME = selftest_prog\n\nall:\n\tcc -Wall -Wextra -Werror -o $(NAME) main.c\n' \
	> "$WORK/sc/real/Makefile"
printf '#!/bin/sh\n# ex04: describe the deliverable.\n# TODO: write the commands.\n:\n' \
	> "$WORK/sc/ex04.sh"
printf '#!/bin/sh\n# ex04: describe the deliverable.\nprintf selftest > selftest-output\n' \
	> "$WORK/sc/real_ex04.sh"

want_green "stub_check: a .c stub passes" -- \
	"$SH" "$TOOLS/stub_check.sh" --file "$WORK/sc/stub.c"
want_red   "stub_check: a .c with a real body fails" -- \
	"$SH" "$TOOLS/stub_check.sh" --file "$WORK/sc/answer.c"
want_green "stub_check: a guards-only .h passes" -- \
	"$SH" "$TOOLS/stub_check.sh" --file "$WORK/sc/guards.h"
want_red   "stub_check: a .h defining the answer macro fails" -- \
	"$SH" "$TOOLS/stub_check.sh" --file "$WORK/sc/macro.h"
want_red   "stub_check: a .h carrying a prototype fails" -- \
	"$SH" "$TOOLS/stub_check.sh" --file "$WORK/sc/proto.h"
want_green "stub_check: a Makefile that only echoes passes" -- \
	"$SH" "$TOOLS/stub_check.sh" --file "$WORK/sc/Makefile"
want_red   "stub_check: a Makefile that compiles fails" -- \
	"$SH" "$TOOLS/stub_check.sh" --file "$WORK/sc/real/Makefile"
want_green "stub_check: a generator reduced to ':' passes" -- \
	"$SH" "$TOOLS/stub_check.sh" --file "$WORK/sc/ex04.sh"
want_red   "stub_check: a generator that still runs commands fails" -- \
	"$SH" "$TOOLS/stub_check.sh" --file "$WORK/sc/real_ex04.sh"

# ---- REPO MODE, which is the mode that decides whether answers get published --
#
# Everything above drives --file mode, and --file mode reads the path it is
# handed. Repo mode does something else: it takes the file LIST from the INDEX
# (git ls-files) and used to read the CONTENT from disk. Those are two different
# trees, and `git commit` publishes the first one.
#
# docs/publishing.md tells the maintainer to run this twice -- after stubbing,
# then "again, over the staged tree". Both runs read the same working-tree
# files, so the second proved nothing the first had not, and an answer left in
# the index behind a stubbed file on disk was reported as a stub. That is the
# whole publish gate reporting OK on the one input it exists to reject.
#
# This needs a populated git repository, which is why repo mode had no arm at
# all. It is worth the fixture: this is the only failure in the repo whose blast
# radius is a permanently public answer.
mkdir -p "$WORK/screpo/c-piscine-c-99/deliverable/ex00"
(
	cd "$WORK/screpo" || exit 1
	git init -q .
	git config user.email selftest@example.invalid
	git config user.name selftest
	# Any body that is not a stub will do, so this one is made up: like
	# ft_selftest_twice and ft_selftest_mix, it answers no exercise. It used to
	# be a working recursive factorial -- c-05 ex01's recursion, shipped in the
	# one file that tests the gate keeping answers out of the template.
	printf 'int\tft_x(int n)\n{\n\tif (n > 7)\n\t\treturn (n - 7);\n\treturn (n * 5);\n}\n' \
		> c-piscine-c-99/deliverable/ex00/ft_x.c
	git add -A && git commit -q -m answer
	# Stub it ON DISK ONLY. The index still holds the answer -- exactly what a
	# forgotten or partial `git add -A` leaves behind.
	printf 'int\tft_x(int n)\n{\n\t(void)n;\n\treturn (0);\n}\n' \
		> c-piscine-c-99/deliverable/ex00/ft_x.c
) >/dev/null 2>&1

want_red   "stub_check: an answer STAGED behind a stubbed file is caught" -- \
	env BUILD_WORKSPACE_DIRECTORY="$WORK/screpo" "$SH" "$TOOLS/stub_check.sh"

# And the reverse, so the arm above is not passing for some unrelated reason:
# once the stub is staged too, the same tree is clean.
( cd "$WORK/screpo" && git add -A && git commit -q -m stubbed ) >/dev/null 2>&1
want_green "stub_check: ... and passes once the stub is the staged content" -- \
	env BUILD_WORKSPACE_DIRECTORY="$WORK/screpo" "$SH" "$TOOLS/stub_check.sh"

# A tracked deliverable of a kind no checker knows must be REPORTED, not
# dropped. --file mode has always exited 2 on one; repo mode silently skipped
# it, which is how c-08's four finished headers once shipped under "OK — all 123
# deliverable(s) are stubs". The same hole is open one kind further along today:
# rush-02 turns in a README.md carrying a teammate's real 42 login and email.
(
	cd "$WORK/screpo" || exit 1
	printf '# By: someone <someone@student.42.fr>\n' \
		> c-piscine-c-99/deliverable/ex00/README.md
	git add -A && git commit -q -m readme
) >/dev/null 2>&1
want_red   "stub_check: a deliverable of an unknown kind is reported" -- \
	env BUILD_WORKSPACE_DIRECTORY="$WORK/screpo" "$SH" "$TOOLS/stub_check.sh"
# ...and counted as a file nothing read, never as an implementation: the tree
# holds one stub and one README, and the summary once said "1 of 1
# deliverable(s) still contain an implementation" over it (Rush 02's two copies
# of 42's dictionary read "2 of 2"), sending a maintainer to hunt an answer in
# files that hold none.
want_out   "stub_check: an unread file is counted apart" \
	"1 file(s) above were never read" -- \
	env BUILD_WORKSPACE_DIRECTORY="$WORK/screpo" "$SH" "$TOOLS/stub_check.sh"
want_broken_none "stub_check: ...and never as an implementation" \
	"still contain an implementation" -- \
	env BUILD_WORKSPACE_DIRECTORY="$WORK/screpo" "$SH" "$TOOLS/stub_check.sh"

# AGENTS.md §0's zone is everything under deliverable/ AND everything under
# generators/, with no third place -- and a zone the checker does not read is a
# zone that ships. Two holes, one fixture: a helper beside a generator, and work
# written at a project's root, where Piscine Reloaded's Vogsphere repo keeps its
# exNN/ folders. Each has a green twin, so the reds are not passing for an
# unrelated reason.
mkdir -p "$WORK/screpo2/c-piscine/c-piscine-c-99/deliverable/ex00" \
	"$WORK/screpo2/c-piscine/c-piscine-c-99/generators"
(
	cd "$WORK/screpo2" || exit 1
	git init -q .
	git config user.email selftest@example.invalid
	git config user.name selftest
	printf 'int\tft_x(int n)\n{\n\t(void)n;\n\treturn (0);\n}\n' \
		> c-piscine/c-piscine-c-99/deliverable/ex00/ft_x.c
	printf '#!/bin/sh\n# Create z.\n# TODO: write the commands.\n:\n' \
		> c-piscine/c-piscine-c-99/generators/ex00.sh
	: > c-piscine/c-piscine-c-99/BUILD.bazel
	printf '# c-piscine-c-99\n' > c-piscine/c-piscine-c-99/README.md
	git add -A && git commit -q -m stubs
) >/dev/null 2>&1
want_green "stub_check: a project's BUILD, README and stubs are fine" -- \
	env BUILD_WORKSPACE_DIRECTORY="$WORK/screpo2" "$SH" "$TOOLS/stub_check.sh"
# A group project's team file sits there too (rush-00's team.bzl: which variant
# the team owes). It is harness configuration, read by the BUILD file, and it
# ships in the template; the third-place rule must not call it work.
( cd "$WORK/screpo2" && printf 'ASSIGNED = ["00"]\n' > c-piscine/c-piscine-c-99/team.bzl &&
	git add -A && git commit -q -m team ) >/dev/null 2>&1
want_green "stub_check: a project's team.bzl is not a third place" -- \
	env BUILD_WORKSPACE_DIRECTORY="$WORK/screpo2" "$SH" "$TOOLS/stub_check.sh"
( cd "$WORK/screpo2" && printf 'touch z\n' > c-piscine/c-piscine-c-99/generators/helper.sh &&
	git add -A && git commit -q -m helper ) >/dev/null 2>&1
want_out   "stub_check: a non-exNN file under generators/ is reported" \
	"generators/helper.sh" -- \
	env BUILD_WORKSPACE_DIRECTORY="$WORK/screpo2" "$SH" "$TOOLS/stub_check.sh"
( cd "$WORK/screpo2" && git rm -q c-piscine/c-piscine-c-99/generators/helper.sh &&
	mkdir -p c-piscine-reloaded/c-piscine-reloaded/ex06 &&
	printf 'int\tft_x(void)\n{\n\treturn (42);\n}\n' \
		> c-piscine-reloaded/c-piscine-reloaded/ex06/ft_x.c &&
	git add -A && git commit -q -m third-place ) >/dev/null 2>&1
want_out   "stub_check: work outside deliverable/ in a project is reported" \
	"no third place" -- \
	env BUILD_WORKSPACE_DIRECTORY="$WORK/screpo2" "$SH" "$TOOLS/stub_check.sh"

# The template ships a placeholder for each of 42's files in tools/resources.tsv,
# beside its project's BUILD file: <file>.DOWNLOAD-ME.txt. It is allowed by its
# exact registered path and nothing wider -- the same name in another project,
# or any other .txt, is still a third place.
( cd "$WORK/screpo2" && git rm -q -r c-piscine-reloaded &&
	mkdir -p tools c-piscine/c-piscine-c-98 &&
	printf 'c-piscine/c-piscine-c-99\tdata.bin\tc-piscine/c-piscine-c-99/data.bin\tharness\t*data.bin\t-\t-\tfixture\n' \
		> tools/resources.tsv &&
	printf 'download data.bin\n' > c-piscine/c-piscine-c-99/data.bin.DOWNLOAD-ME.txt &&
	git add -A && git commit -q -m placeholder ) >/dev/null 2>&1
want_green "stub_check: a registered file's placeholder is not a third place" -- \
	env BUILD_WORKSPACE_DIRECTORY="$WORK/screpo2" "$SH" "$TOOLS/stub_check.sh"
( cd "$WORK/screpo2" && : > c-piscine/c-piscine-c-98/BUILD.bazel &&
	printf 'download data.bin\n' > c-piscine/c-piscine-c-98/data.bin.DOWNLOAD-ME.txt &&
	git add -A && git commit -q -m elsewhere ) >/dev/null 2>&1
want_out   "stub_check: ...but the same name in another project is" \
	"c-piscine-c-98/data.bin.DOWNLOAD-ME.txt" -- \
	env BUILD_WORKSPACE_DIRECTORY="$WORK/screpo2" "$SH" "$TOOLS/stub_check.sh"

# 42's file itself, at the one path its row names, is not a third place either:
# every consumer of the registry follows from the row, and this list used to
# name resources.tar.gz and *.dict instead -- so a newly registered file at a
# project root was reported, while any .dict anywhere went through. Each has a
# twin: the registered file at another path, and an unregistered .dict.
( cd "$WORK/screpo2" && git rm -q c-piscine/c-piscine-c-98/data.bin.DOWNLOAD-ME.txt &&
	printf 'bytes\n' > c-piscine/c-piscine-c-99/data.bin &&
	git add -A && git commit -q -m registered ) >/dev/null 2>&1
want_green "stub_check: a registered file at its path is not a third place" -- \
	env BUILD_WORKSPACE_DIRECTORY="$WORK/screpo2" "$SH" "$TOOLS/stub_check.sh"
( cd "$WORK/screpo2" && printf 'bytes\n' > c-piscine/c-piscine-c-98/data.bin &&
	git add -A && git commit -q -m unregistered-path ) >/dev/null 2>&1
want_out   "stub_check: ...but the same file at another path is" \
	"c-piscine-c-98/data.bin" -- \
	env BUILD_WORKSPACE_DIRECTORY="$WORK/screpo2" "$SH" "$TOOLS/stub_check.sh"
( cd "$WORK/screpo2" && git rm -q c-piscine/c-piscine-c-98/data.bin &&
	printf 'zero: zero\n' > c-piscine/c-piscine-c-99/words.dict &&
	git add -A && git commit -q -m dict ) >/dev/null 2>&1
want_out   "stub_check: ...and so is a .dict nobody registered" \
	"c-piscine-c-99/words.dict" -- \
	env BUILD_WORKSPACE_DIRECTORY="$WORK/screpo2" "$SH" "$TOOLS/stub_check.sh"

# The approved-header pins are by CONTENT, and this is the arm that proves it.
# The fixture is named ft_list.h and shaped like ft_list.h — a path- or
# basename-keyed allowlist would wave it straight through — but its bytes are
# not the approved ones, so it must go red. That distinction is the whole reason
# the pin is a hash: "someone forgot to reduce this header" and "this header is
# the reviewed one" are the same path, and only the content tells them apart.
printf '%s\n\n#ifndef FT_LIST_H\n# define FT_LIST_H\n\ntypedef struct s_list\n{\n\tstruct s_list\t*next;\n\tvoid\t\t\t*data;\n}\t\t\t\tt_list;\n\n#endif\n' \
	"$SC_H" > "$WORK/sc/ft_list.h"
want_red   "stub_check: a header is approved by its bytes, not by its name" -- \
	"$SH" "$TOOLS/stub_check.sh" --file "$WORK/sc/ft_list.h"

# ...and not by its bytes ALONE either. Approval is (hash, path), because the
# first version keyed on content and c-09's includes/ft.h (approved then, not
# now) held the same five prototypes as c-08 ex00's ft.h -- so approving one
# approved the other, and c-08 ex00 shipped its answer and went GREEN. Identical
# bytes, opposite meanings, decided by where the file sits. These two are
# byte-identical and neither is at an approved path, so both must be red.
cp "$WORK/sc/ft_list.h" "$WORK/sc/ft_list_elsewhere.h"
want_red   "stub_check: identical bytes, first path" -- \
	"$SH" "$TOOLS/stub_check.sh" --file "$WORK/sc/ft_list.h"
want_red   "stub_check: identical bytes, second path" -- \
	"$SH" "$TOOLS/stub_check.sh" --file "$WORK/sc/ft_list_elsewhere.h"

# And the hash itself must ignore the 42 header, or every re-stamp would revoke
# every approval. Same bytes below the block, two different identities in it.
printf '/* By: marvin <marvin@42.fr> */\n#ifndef X_H\n# define X_H\n#endif\n' > "$WORK/sc/h1.h"
printf '/* By: someone <someone@42.fr> */\n#ifndef X_H\n# define X_H\n#endif\n' > "$WORK/sc/h2.h"
_h1=$("$SH" "$TOOLS/stub_check.sh" --hash "$WORK/sc/h1.h" | cut -d' ' -f1)
_h2=$("$SH" "$TOOLS/stub_check.sh" --hash "$WORK/sc/h2.h" | cut -d' ' -f1)
# The emptiness test is the point. This was one `[ "$(...)" = "$(...)" ]`, so a
# --hash mode that printed NOTHING AT ALL compared "" with "" and the arm
# reported success -- an assertion that two hashes agree, satisfied by there
# being no hashes. A 32-character md5 prefix is what it is supposed to produce.
if [ ${#_h1} -ne 32 ] || [ ${#_h2} -ne 32 ]; then
	printf '  %-52s %s\n' "stub_check: --hash ignores the 42 header block" \
		"FAIL < (--hash produced no hash: '$_h1' / '$_h2')"
	FAIL=$((FAIL + 1))
elif [ "$_h1" = "$_h2" ]; then
	printf '  %-52s %s\n' "stub_check: --hash ignores the 42 header block" "ok (green, as required)"
	PASS=$((PASS + 1))
else
	printf '  %-52s %s\n' "stub_check: --hash ignores the 42 header block" \
		"FAIL < (a re-stamp would revoke every approval)"
	FAIL=$((FAIL + 1))
fi

# ...and it must NOT ignore anything else that shares a line with a comment.
# `^/\*.*\*/$` reads as "a line that is one comment", but `.*` is greedy, so
# it also matched a line whose middle is code between two comment markers.
# Reproduced: the pair below, differing by a whole variable definition,
# produced the same hash -- so an approved entry approved the smuggled copy.
printf '/* By: marvin <marvin@42.fr> */\n/* */ int g_answer = 42; /* */\n#ifndef X_H\n# define X_H\n#endif\n' > "$WORK/sc/h3.h"
_h3=$("$SH" "$TOOLS/stub_check.sh" --hash "$WORK/sc/h3.h" | cut -d' ' -f1)
if [ ${#_h3} -ne 32 ]; then
	printf '  %-52s %s\n' "stub_check: --hash sees code between two comments" \
		"FAIL < (--hash produced no hash: '$_h3')"
	FAIL=$((FAIL + 1))
elif [ "$_h3" != "$_h1" ]; then
	printf '  %-52s %s\n' "stub_check: --hash sees code between two comments" "ok (green, as required)"
	PASS=$((PASS + 1))
else
	printf '  %-52s %s\n' "stub_check: --hash sees code between two comments" \
		"FAIL < (a definition hashed the same as no line at all)"
	FAIL=$((FAIL + 1))
fi

# THE DEPTH A LINE IS JUDGED AT. Braces used to be counted after the line was
# scored, so everything sharing a line with its own opening brace was scored at
# depth 0 -- outside every function body, where anything is allowed. A whole
# working function written on one line was reported as a stub.
printf 'int\tft_double(int n) { return (n * 2); }\n' > "$WORK/sc/oneline.c"
printf 'int\tft_f(void)\n{\tint i;\n\treturn (0);\n}\n' > "$WORK/sc/braceline.c"
want_red   "stub_check: a whole function on one line is not a stub" -- \
	"$SH" "$TOOLS/stub_check.sh" --file "$WORK/sc/oneline.c"
want_red   "stub_check: a declaration on the brace line is examined" -- \
	"$SH" "$TOOLS/stub_check.sh" --file "$WORK/sc/braceline.c"
# ...and the forms a real stub is written in must still pass, on one line too:
# the fix must not turn `{ return (0); }` into a finding.
printf 'int\tft_f(void) { return (0); }\n\nvoid\tft_g(int n) { (void)n; }\n' > "$WORK/sc/onelinestub.c"
want_green "stub_check: a one-line stub body still passes" -- \
	"$SH" "$TOOLS/stub_check.sh" --file "$WORK/sc/onelinestub.c"

# ONE NAME PER LINE (stub_check.sh says so at its lists). They were strings
# walked with `for f in $c_files`, which splits a name at its blanks: a staged
# answer named `ft_x copy.c` -- the name a file manager gives a duplicate --
# was scored as `ft_x` and `copy.c`, two paths the index does not have. The
# refusal for a blob it could not read was made inside $(...), so it ended the
# substitution and not the run, and awk, handed an empty name, read stdin: OK,
# exit 0, over an answer that would have shipped (found rehearsing a template
# publish, 2026-10-03), and a verdict that changed with whatever was piped in. --file
# split the same way, said `awk: cannot open` and then OK. Every arm below was
# red on that code. The repo-mode runs take stdin from /dev/null, so that a
# hand run against a checker that reads it fails here rather than hangs.
mkdir -p "$WORK/sc/blank"
cp "$WORK/sc/answer.c" "$WORK/sc/blank/ft_x copy.c"
cp "$WORK/sc/stub.c" "$WORK/sc/blank/ft_stub copy.c"
want_red   "stub_check: --file reads a name with a blank whole" -- \
	"$SH" "$TOOLS/stub_check.sh" --file "$WORK/sc/blank/ft_x copy.c"
want_green "stub_check: ...and passes a stub of that name" -- \
	"$SH" "$TOOLS/stub_check.sh" --file "$WORK/sc/blank/ft_stub copy.c"
sc_repo() { env BUILD_WORKSPACE_DIRECTORY="$1" "$SH" "$TOOLS/stub_check.sh" < /dev/null; }
# The text of an answer on stdin, over a tree of stubs: the old run scored it
# as the content of `ft_x`, one half of `ft_x (1).c`, and reported it.
sc_piped() {
	printf 'int\tft_selftest_one(void)\n{\n\treturn (1);\n}\n' |
		env BUILD_WORKSPACE_DIRECTORY="$1" "$SH" "$TOOLS/stub_check.sh"
}
mkdir -p "$WORK/screpo3/c-piscine/c-piscine-c-99/deliverable/ex00"
(
	cd "$WORK/screpo3" || exit 1
	git init -q .
	git config user.email selftest@example.invalid
	git config user.name selftest
	cp "$WORK/sc/stub.c" c-piscine/c-piscine-c-99/deliverable/ex00/ft_x.c
	cp "$WORK/sc/stub.c" "c-piscine/c-piscine-c-99/deliverable/ex00/ft_x (1).c"
	git add -A && git commit -q -m stubs
) > /dev/null 2>&1
want_green "stub_check: what is piped in is never scored" -- sc_piped "$WORK/screpo3"
( cd "$WORK/screpo3" && cp "$WORK/sc/answer.c" "c-piscine/c-piscine-c-99/deliverable/ex00/ft_x copy.c" &&
	git add -A && git commit -q -m answer ) > /dev/null 2>&1
want_red   "stub_check: a staged answer named with a blank is caught" -- sc_repo "$WORK/screpo3"
want_out   "stub_check: ...under its whole name" \
	"c-piscine-c-99/deliverable/ex00/ft_x copy.c" -- sc_repo "$WORK/screpo3"
# A name git quotes in a listing -- a byte above 0x7f, here an e with an acute
# accent -- is a name too: listed quoted, it was a path `git show :` could not
# find, and an unread file of no known kind.
( cd "$WORK/screpo3" && git rm -q "c-piscine/c-piscine-c-99/deliverable/ex00/ft_x copy.c" &&
	cp "$WORK/sc/stub.c" "c-piscine/c-piscine-c-99/deliverable/ex00/ft_$(printf '\303\251').c" &&
	git add -A && git commit -q -m accent ) > /dev/null 2>&1
want_green "stub_check: a name git would quote is read as it is" -- sc_repo "$WORK/screpo3"
# And a blob the index cannot give -- a path a merge left in conflict, at
# stages 1 and 2 and not at 0 -- is refused, and the refusal ends the run with
# 2: it was printed, then the file was scored as empty and the run said OK.
(
	cd "$WORK/screpo3" || exit 1
	_scb=$(git hash-object -w "$WORK/sc/stub.c")
	_scf=c-piscine/c-piscine-c-99/deliverable/ex00/ft_x.c
	printf '0 0000000000000000000000000000000000000000\t%s\n' "$_scf" | git update-index --index-info
	printf '100644 %s 1\t%s\n100644 %s 2\t%s\n' "$_scb" "$_scf" "$_scb" "$_scf" |
		git update-index --index-info
) > /dev/null 2>&1
want_broken "stub_check: a blob the index cannot give ends the run" \
	"Refusing to score it, and so the whole run" -- sc_repo "$WORK/screpo3"
# A bare name shaped like an awk assignment -- `ft_a=b.c`, relative, in the
# directory the run starts from -- was taken by awk for one: awk then read its
# standard input, /dev/null, and an answer under that name was "OK -- all 1
# deliverable(s) are stubs", its --hash the empty file's. Each judge, and the
# hash, now reads its file by redirection.
mkdir -p "$WORK/sc/assign"
cp "$WORK/sc/answer.c" "$WORK/sc/assign/ft_a=b.c"
cp "$WORK/sc/h3.h" "$WORK/sc/assign/ft_a=b.h"
SC_ABS="$(cd "$TOOLS" && pwd)/stub_check.sh"
sc_here() { ( cd "$WORK/sc/assign" && "$SH" "$SC_ABS" "$@" ); }
want_red   "stub_check: --file reads a name shaped like an awk assignment" -- \
	sc_here --file ft_a=b.c
# The hash of that name is its content's: h3.h's, a 32-character md5, never
# the empty input's.
sc_hash_same() {
	_sca=$(sc_here --hash ft_a=b.h | cut -d' ' -f1)
	_scb=$("$SH" "$SC_ABS" --hash "$WORK/sc/h3.h" | cut -d' ' -f1)
	[ ${#_sca} -eq 32 ] && [ "$_sca" = "$_scb" ]
}
want_green "stub_check: --hash of such a name is its content's" -- sc_hash_same

# ---------------------------------------------------------------- placeholder_pdf
# The PDF the public template ships where each 42 subject was. Nothing opens it
# in the suite, so the arms check what a PDF reader is strict about and a person
# would never notice until a viewer refused the file: the byte offset of every
# object in the cross-reference table, of the table itself in startxref, and the
# stream's /Length. The script MEASURES those from the file as it writes it, so
# these arms are what would catch a change that started computing them instead.
mkdir -p "$WORK/pp"
"$SH" "$TOOLS/placeholder_pdf.sh" "$WORK/pp/p.pdf" c-piscine-c-05 > /dev/null 2>&1
pp_offsets() {
	awk '
		{ line[NR] = $0; at[NR] = off; off += length($0) + 1 }
		/^[0-9]+ 0 obj$/ { split($0, a, " "); obj[a[1]] = at[NR] }
		/^<< \/Length [0-9]+ >>$/ { split($0, a, " "); len = a[3] }
		$0 == "stream" { s0 = off }
		$0 == "endstream" { s1 = at[NR] - 1 }
		$0 == "xref" { xat = at[NR]; xl = NR }
		$0 == "startxref" { sx = NR + 1 }
		END {
			if (line[1] != "%PDF-1.4" || line[NR] != "%%EOF") exit 1
			if (xl == 0 || line[sx] + 0 != xat) exit 1
			if (len + 0 != s1 - s0) exit 1
			for (i = 1; i <= 5; i++) {
				split(line[xl + 2 + i], f, " ")
				if (!(i in obj) || f[1] + 0 != obj[i]) exit 1
			}
		}' "$1"
}
want_green "placeholder_pdf: every offset points where it claims" -- \
	pp_offsets "$WORK/pp/p.pdf"
want_green "placeholder_pdf: ... and it names the project" -- \
	grep -q "Project: c-piscine-c-05" "$WORK/pp/p.pdf"
